function targetNodeOptions(cid,selected){const nodes=state.resources.filter(r=>r.type==='node'&&r.connection_id===cid).sort((a,b)=>String(a.node).localeCompare(String(b.node),'de',{numeric:true})),online=nodes.filter(n=>n.status==='online'),pick=online.some(n=>n.node===selected)?selected:online[0]?.node;return nodes.map(n=>`<option value="${esc(n.node)}" ${n.node===pick?'selected':''} ${n.status==='online'?'':'disabled'}>${esc(n.node)}${n.status==='online'?` · CPU ${Math.round((n.cpu||0)*100)} % · RAM ${percent(n.mem||0,n.maxmem||0)} %`:' · offline'}</option>`).join('')}
