function globalSearchResults(q){q=String(q||'').trim().toLowerCase();if(!q)return[];const out=[];for(const [page,title] of Object.entries(pageTitles))if(title.toLowerCase().includes(q))out.push({kind:'Seite',label:title,nav:page,icon:pageIcons[page]||'grid'});for(const v of state.resources.filter(r=>['qemu','lxc'].includes(r.type)&&(String(r.name||'').toLowerCase().includes(q)||String(r.vmid).includes(q))).slice(0,6))out.push({kind:v.type==='lxc'?'Container':'VM',label:(v.name||'VM '+v.vmid)+' · '+v.vmid,vm:v.connection_id+':'+v.vmid,icon:v.type==='lxc'?'box':'vm',meta:v.node});for(const n of state.resources.filter(r=>r.type==='node'&&String(r.node).toLowerCase().includes(q)).slice(0,4))out.push({kind:'Host',label:n.node,nav:'clusters',icon:'server',meta:state.connections.find(c=>c.id===n.connection_id)?.name||''});for(const [tab,label] of settingsTabsNav)if(label.toLowerCase().includes(q))out.push({kind:'Einstellung',label,settings:tab,icon:'settings'});return out.slice(0,10)}
