function head(kicker,title,desc,actions=''){if(!state.headInfo)state.headInfo={title,desc};return `<div class="pagehead"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
const newVmButton=()=>`<button class="primary" data-nav="market">${icon('plus')} VM bereitstellen</button>`;
const refreshButton=()=>`<button class="btn-icon ghost" data-action="refresh" aria-label="Daten aktualisieren">${icon('refresh')}</button>`;
function statusTag(status){const labels={online:'Online',offline:'Offline',unknown:'Unbekannt',reviewed:'Manuell geprüft',running:'Läuft',stopped:'Gestoppt',queued:'Eingeplant',completed:'Abgeschlossen',failed:'Fehlgeschlagen',needs_attention:'Prüfung nötig'};return `<span class="status-tag ${['failed','needs_attention','offline'].includes(status)?'fail':status==='queued'?'warn':['stopped','unknown','reviewed'].includes(status)?'neutral':''}"><span class="dot ${status==='queued'?'amber':''}"></span>${labels[status]||esc(status)}</span>`}
function totals(){const resources=state.resources.filter(r=>state.scope==='all'||r.connection_id===state.scope),nodes=resources.filter(r=>r.type==='node'),vms=resources.filter(r=>['qemu','lxc'].includes(r.type)&&!r.template),cpuMax=nodes.reduce((s,r)=>s+(r.maxcpu||0),0),memMax=nodes.reduce((s,r)=>s+(r.maxmem||0),0),mem=nodes.reduce((s,r)=>s+(r.mem||0),0),cpu=cpuMax?Math.round(nodes.reduce((s,r)=>s+(r.cpu||0)*(r.maxcpu||0),0)/cpuMax*100):0;return{nodes,vms,cpuMax,memMax,mem,cpu}}
function spark(){return `<svg class="spark" viewBox="0 0 60 20" aria-hidden="true"><path d="M1 16l7-5 7 2 7-7 7 4 7-5 7 4 7-5 9 3" fill="none" stroke="#8ce8cd" stroke-width="1.5"/></svg>`}
function stats(){const t=totals(),memPct=percent(t.mem,t.memMax),online=t.nodes.filter(n=>n.status==='online').length,running=t.vms.filter(v=>v.status==='running').length,offline=t.nodes.length-online;const cards=[['server','Hosts',t.nodes.length,'',online+' online'+(offline?` · <b class="text-warn">${offline} offline</b>`:''),null],['vm','VMs & Container',t.vms.length,'',running+' laufend · '+(t.vms.length-running)+' gestoppt',null],['cpu','CPU-Auslastung',t.cpu,'%',t.cpuMax+' Kerne gesamt',t.cpu],['memory','Arbeitsspeicher',memPct,'%',fmtBytes(t.mem)+' / '+fmtBytes(t.memMax),memPct]];return `<section class="stats" aria-label="Ressourcenübersicht">${cards.map(([i,l,v,u,f,bar])=>{const level=bar===null?'':bar>=90?'crit':bar>=75?'high':'';return `<div class="stat ${level?'is-'+level:''}"><div class="stat-top">${l}${icon(i)}</div><div class="stat-value">${v}<small>${u}</small></div>${bar===null?'':`<span class="usage-track" role="presentation"><i class="${level}" style="width:${Math.max(0,Math.min(100,bar))}%"></i></span>`}<div class="stat-foot">${f}</div></div>`}).join('')}</section>`}
function ring(value,label='',opts={}){const p=value===null||value===undefined||Number.isNaN(+value)?null:Math.max(0,Math.min(100,Math.round(+value))),r=15.5,c=2*Math.PI*r,level=opts.level||(p===null?'none':p>=90?'crit':p>=75?'high':'ok');return `<span class="ring ring-${opts.size||'md'} ring-${level}" role="img" aria-label="${esc(label)} ${p===null?'keine Daten':p+' %'}"><svg viewBox="0 0 36 36" aria-hidden="true"><circle class="ring-track" cx="18" cy="18" r="${r}"/><circle class="ring-value" cx="18" cy="18" r="${r}" stroke-dasharray="${p===null?0:(c*p/100).toFixed(2)} ${c.toFixed(2)}" transform="rotate(-90 18 18)"/></svg><b>${opts.text??(p===null?'—':p+(opts.unit??'%'))}</b></span>`}
function storageTotals(resources){const seen=new Set();let used=0,total=0;for(const r of resources){if(r.type!=='storage'||r.status!=='available'||!r.maxdisk)continue;const key=r.shared?r.connection_id+':'+r.storage:r.connection_id+':'+r.node+':'+r.storage;if(seen.has(key))continue;seen.add(key);used+=r.disk||0;total+=r.maxdisk||0}return{used,total,pct:total?percent(used,total):null}}
function clusterSummaries(){return state.connections.filter(c=>c.kind!=='pbs'&&(state.scope==='all'||c.id===state.scope)).map(c=>{const rs=state.resources.filter(r=>r.connection_id===c.id),nodes=rs.filter(r=>r.type==='node'),online=nodes.filter(n=>n.status==='online'),guests=rs.filter(r=>['qemu','lxc'].includes(r.type)&&!r.template),cpuMax=online.reduce((s,n)=>s+(n.maxcpu||0),0),memMax=online.reduce((s,n)=>s+(n.maxmem||0),0),st=storageTotals(rs);return{c,nodes,online,guests,running:guests.filter(g=>g.status==='running').length,cpu:cpuMax?Math.round(online.reduce((s,n)=>s+(n.cpu||0)*(n.maxcpu||0),0)/cpuMax*100):null,mem:memMax?percent(online.reduce((s,n)=>s+(n.mem||0),0),memMax):null,storage:st.pct,stale:rs.some(r=>r.stale)}})}
function healthScore(t,storagePct){const alerts=typeof alertState==='function'?alertState().alerts.filter(a=>a.state==='firing'&&!a.acknowledged):[],crit=alerts.filter(a=>a.severity==='critical').length,warn=alerts.length-crit,offline=t.nodes.filter(n=>n.status!=='online').length,failed=[...state.jobs,...state.operations].filter(j=>['failed','needs_attention'].includes(j.status)).length,memPct=percent(t.mem,t.memMax);let s=100-offline*20-crit*8-warn*3-failed*4;for(const v of [t.cpu,memPct,storagePct])if(v!==null&&v>=85)s-=v>=95?12:6;s=Math.max(0,Math.min(100,Math.round(s)));return{score:s,label:!t.nodes.length?'Keine Daten':s>=85?'Gut':s>=60?'Eingeschränkt':'Kritisch',level:!t.nodes.length?'none':s>=85?'ok':s>=60?'high':'crit',crit,warn,offline,failed}}
function overview(){const t=totals(),scoped=state.resources.filter(r=>state.scope==='all'||r.connection_id===state.scope),st=storageTotals(scoped),h=healthScore(t,st.pct),running=t.vms.filter(v=>v.status==='running').length,clusters=clusterSummaries(),onlineNodes=t.nodes.filter(n=>n.status==='online').length,memPct=percent(t.mem,t.memMax);
const bar=(name,v)=>`<div class="hbar"><span>${name}</span><span class="usage-track" role="presentation"><i class="${v>=90?'crit':v>=75?'high':''}" style="width:${v??0}%"></i></span><b>${v===null?'—':v+' %'}</b></div>`;
const kpi=(iconName,value,total,label,cls='')=>`<div class="kpi ${cls}"><span class="kpi-icon">${icon(iconName)}</span><div><b>${value}${total!==undefined?`<small>/${total}</small>`:''}</b><span>${label}</span></div></div>`;
return head('','Dashboard','Zustand, Kapazität und Aufgaben aller verbundenen Umgebungen.',refreshButton()+newVmButton())
+`<section class="panel health-card"><div class="health-main">${ring(t.nodes.length?h.score:null,'Health-Score',{size:'xl',level:h.level,text:t.nodes.length?String(h.score):'—'})}<div><div class="health-title"><b>Infrastruktur-Health</b>${h.crit||h.warn?`<button class="text-button health-alerts" data-nav="alerts">${icon('bell')} ${h.crit} kritisch, ${h.warn} Warnungen</button>`:''}</div><div class="health-label level-${h.level}">${h.label}</div><div class="health-facts"><span>${icon('server')} ${clusters.length} Cluster</span><span>${icon('server')} ${onlineNodes}/${t.nodes.length} Hosts online</span><span class="fact-ok">▶ ${running} laufend</span><span>■ ${t.vms.length-running} gestoppt</span><span>${icon('vm')} ${t.vms.length} Gäste</span></div>${!t.nodes.length?`<div class="panel-actions"><button class="primary" data-nav="settings">Einrichtung starten ${icon('arrow')}</button></div>`:''}</div></div><div class="health-bars">${bar('CPU',t.nodes.length?t.cpu:null)}${bar('RAM',t.nodes.length?memPct:null)}${bar('Storage',st.pct)}</div></section>`
+`<section class="kpi-row" aria-label="Kennzahlen">${kpi('server',clusters.length,undefined,'Cluster')}${kpi('server',onlineNodes,t.nodes.length,'Hosts online',onlineNodes<t.nodes.length?'is-warn':'')}${kpi('vm',running,undefined,'Gäste laufend','is-ok')}${kpi('vm',t.vms.length-running,undefined,'Gäste gestoppt')}<div class="kpi">${ring(t.nodes.length?t.cpu:null,'CPU')}<div><b>CPU</b><span>${t.cpuMax} Kerne</span></div></div><div class="kpi">${ring(t.nodes.length?memPct:null,'RAM')}<div><b>RAM</b><span>${fmtBytes(t.mem)} / ${fmtBytes(t.memMax)}</span></div></div><div class="kpi">${ring(st.pct,'Storage')}<div><b>Storage</b><span>${st.total?fmtBytes(st.used)+' / '+fmtBytes(st.total):'keine Daten'}</span></div></div></section>`
+(clusters.length?`<div class="section-title"><h2>Cluster</h2><span class="muted">${clusters.length} verbunden</span></div><div class="cluster-grid">${clusters.map(x=>{const down=x.nodes.length&&!x.online.length,partial=x.online.length<x.nodes.length,level=down||x.stale?'crit':partial?'high':'ok';return `<article class="cluster-card level-${level}"><header><span class="cluster-icon">${icon('server')}<i class="dot"></i></span><div><b>${esc(x.c.name)}</b><small>${esc((x.c.url||'').replace(/^https?:\/\//,''))}</small></div><span class="cluster-state">${down||x.stale?'Offline':partial?'Eingeschränkt':'Online'}</span></header><div class="cluster-metrics"><div class="cluster-count"><b>${x.online.length}<small>/${x.nodes.length}</small></b><span>Hosts</span></div><div>${ring(x.cpu,'CPU',{size:'sm'})}<span>CPU</span></div><div>${ring(x.mem,'RAM',{size:'sm'})}<span>RAM</span></div><div>${ring(x.storage,'Storage',{size:'sm'})}<span>Storage</span></div><div class="cluster-count"><b>${x.running}<small>/${x.guests.length}</small></b><span>Gäste</span></div></div><footer><span class="muted">${state.updated?'Aktualisiert '+new Date(state.updated).toLocaleTimeString('de-DE'):'—'}</span><button class="text-button" data-cluster-open="${esc(x.c.id)}" aria-label="${esc(x.c.name)} öffnen">${icon('arrow')}</button></footer></article>`}).join('')}</div>`:'')
+`<div class="content-grid"><section class="panel panel-pad"><div class="panelhead"><h2>Ressourcen pro Host</h2><div class="legend"><span><i></i>CPU</span><span><i></i>RAM</span></div></div>${nodeCapacity(t.nodes)}</section><section class="panel panel-pad"><div class="panelhead"><h2>Letzte Bereitstellungen</h2><button class="text-button" data-nav="jobs">Alle Aufgaben ${icon('arrow')}</button></div>${activity()}</section></div><section class="panel" style="margin-top:16px"><div class="table-toolbar"><h2>Hosts</h2><button class="text-button" data-nav="clusters">Cluster & Hosts öffnen ${icon('arrow')}</button></div>${nodesTable(t.nodes)}</section>`}
function demoChart(){return `<svg class="chart" viewBox="0 0 600 170" preserveAspectRatio="none" role="img" aria-label="Illustrativer CPU- und RAM-Tagesverlauf, Beispieldaten"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#8ce8cd" stop-opacity=".15"/><stop offset="100%" stop-color="#8ce8cd" stop-opacity="0"/></linearGradient></defs><path d="M0 20H600M0 65H600M0 110H600M0 155H600" stroke="#253447" stroke-dasharray="3 6" fill="none"/><path d="M0 123L20 119L40 126L60 104L80 111L100 94L120 105L140 96L160 101L180 77L200 87L220 58L240 72L260 53L280 66L300 48L320 65L340 73L360 53L380 66L400 79L420 69L440 91L460 81L480 97L500 82L520 88L540 70L560 80L580 65L600 76V170H0Z" fill="url(#area)"/><path d="M0 123L20 119L40 126L60 104L80 111L100 94L120 105L140 96L160 101L180 77L200 87L220 58L240 72L260 53L280 66L300 48L320 65L340 73L360 53L380 66L400 79L420 69L440 91L460 81L480 97L500 82L520 88L540 70L560 80L580 65L600 76" stroke="#8ce8cd" stroke-width="2" fill="none"/><path d="M0 96L40 93L80 96L120 82L160 86L200 75L240 78L280 64L320 70L360 61L400 66L440 60L480 64L520 53L560 61L600 57" stroke="#738cd5" stroke-width="2" fill="none"/></svg><div class="chart-labels"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>23:59</span></div><div class="small muted" style="margin-top:15px;font-size:9px">Illustrativer Verlauf · nicht gemessen</div>`}
function nodeCapacity(nodes){if(!nodes.length)return empty('server','Noch keine Messwerte','Proxmox verbinden, um die aktuelle Auslastung zu sehen.');return `<div style="margin-top:22px">${nodes.map(n=>`<div style="margin-bottom:20px"><div class="inline"><span class="mono">${esc(n.node)}</span><span class="mono muted">CPU ${Math.round((n.cpu||0)*100)}% · RAM ${percent(n.mem,n.maxmem)}%</span></div><div class="mini-bar" style="width:100%;margin-top:10px"><i style="width:${Math.round((n.cpu||0)*100)}%"></i></div><div class="mini-bar" style="width:100%;margin-top:6px"><i style="width:${percent(n.mem,n.maxmem)}%;background:#738cd5"></i></div></div>`).join('')}</div>`}
function activity(){if(!state.jobs.length)return `<div class="activity-list"><div class="activity"><div class="activity-symbol">${icon('check')}</div><div><div class="activity-title">${state.mode==='demo'?'Workspace bereit zum Erkunden':'Noch keine Bereitstellungen'}</div><div class="activity-meta">${state.mode==='demo'?'Marketplace öffnen und Demo-VM konfigurieren':'Blueprint veröffentlichen und erste VM erstellen'}</div></div></div></div>`;return `<div class="activity-list">${state.jobs.slice(0,4).map(j=>`<div class="activity"><div class="activity-symbol">${icon(j.status==='completed'?'check':'activity')}</div><div style="min-width:0;flex:1"><button class="text-button" data-job="${esc(j.id)}" style="text-align:left;overflow-wrap:anywhere">${esc(j.name)}</button><div class="activity-meta">${esc(j.blueprint)} · ${when(j.created)}</div></div></div>`).join('')}</div>`}
function nodesTable(nodes){if(!nodes.length)return empty('server','Keine Nodes verbunden','Unter Einstellungen › Verbindungen die erste Proxmox-Verbindung hinzufügen.',`<button class="primary" data-nav="settings">Verbindung einrichten ${icon('arrow')}</button>`);return `<div class="table-wrap" tabindex="0" role="region" aria-label="Node-Tabelle"><table><thead><tr><th>Host / Verbindung</th><th>Status</th><th class="usage-column">CPU</th><th class="usage-column">Arbeitsspeicher</th><th class="num">Gäste</th></tr></thead><tbody>${nodes.map(n=>`<tr><td><div class="table-name"><span class="table-symbol">${icon('server')}</span><div><b>${esc(n.node)}</b><small>${esc(state.connections.find(c=>c.id===n.connection_id)?.name||'Proxmox')}</small></div></div></td><td>${statusTag(n.status)}</td><td>${n.status==='online'?usageBar((n.cpu||0)*100,n.maxcpu?n.maxcpu+' Kerne':'')+(n.metrics_stale?'<small class="metric-stale">veraltet</small>':''):'<span class="muted">—</span>'}</td><td>${n.status==='online'?usageBar(percent(n.mem||0,n.maxmem||0),fmtBytes(n.mem||0)+' / '+fmtBytes(n.maxmem||0)):'<span class="muted">—</span>'}</td><td class="num">${totals().vms.filter(v=>v.node===n.node&&v.connection_id===n.connection_id).length}</td></tr>`).join('')}</tbody></table></div>`}
function clusters(){return head('','Infrastruktur','Hosts, Zustand und Auslastung aller verbundenen Proxmox-Cluster.',refreshButton())+stats()+`<section class="panel"><div class="table-toolbar"><h2>Alle Nodes</h2><button class="text-button" data-nav="settings">Verbindung hinzufügen ${icon('plus')}</button></div>${nodesTable(totals().nodes)}</section>`}
function empty(i,title,desc,button=''){return `<div class="empty"><div class="empty-symbol">${icon(i)}</div><h2>${title}</h2><p>${desc}</p>${button}</div>`}
const vmSortKeys={name:v=>String(v.name||'').toLowerCase(),vmid:v=>Number(v.vmid)||0,status:v=>String(v.status||''),node:v=>String(v.node||''),maxcpu:v=>Number(v.maxcpu)||0,cpu:v=>v.status==='running'?Number(v.cpu)||0:-1,mem:v=>v.maxmem?(Number(v.mem)||0)/v.maxmem:0,type:v=>String(v.type||'')};
const vmFilters={all:v=>!isTemplate(v),running:v=>!isTemplate(v)&&v.status==='running',stopped:v=>!isTemplate(v)&&v.status!=='running',qemu:v=>!isTemplate(v)&&v.type!=='lxc',lxc:v=>!isTemplate(v)&&v.type==='lxc',template:v=>isTemplate(v)};
const isTemplate=v=>v.template==1||v.template===true;
function inventoryGuests(){return state.resources.filter(r=>(state.scope==='all'||r.connection_id===state.scope)&&['qemu','lxc'].includes(r.type))}
function usageBar(value,label=''){const p=Math.max(0,Math.min(100,Math.round(Number(value)||0)));return `<div class="usage"><div class="usage-line"><span class="usage-value">${p} %</span>${label?`<small>${label}</small>`:''}</div><span class="usage-track" role="presentation"><i class="${p>=90?'crit':p>=75?'high':''}" style="width:${p}%"></i></span></div>`}
function visibleVMs(){const q=String(state.query||'').toLowerCase(),filter=vmFilters[state.vmFilter]||vmFilters.all,sort=state.vmSort||{key:'name',dir:1},key=vmSortKeys[sort.key]||vmSortKeys.name;return inventoryGuests().filter(v=>[v.name,v.vmid,v.node].some(x=>String(x??'').toLowerCase().includes(q))).filter(filter).sort((a,b)=>{const x=key(a),y=key(b);return ((x<y?-1:x>y?1:0)*sort.dir)||((Number(a.vmid)||0)-(Number(b.vmid)||0))})}
function vms(){const all=inventoryGuests(),v=visibleVMs(),sort=state.vmSort||{key:'name',dir:1},active=state.vmFilter&&vmFilters[state.vmFilter]?state.vmFilter:'all',selectable=v.filter(x=>['qemu','lxc'].includes(x.type)).map(x=>x.connection_id+':'+x.vmid),allSelected=selectable.length>0&&selectable.every(k=>state.selectedVMs.includes(k));
const th=(k,label,cls='')=>`<th class="sortable ${cls}" aria-sort="${sort.key===k?(sort.dir>0?'ascending':'descending'):'none'}"><button type="button" data-vm-sort="${k}">${label}<span class="sort-mark" aria-hidden="true">${sort.key===k?(sort.dir>0?'↑':'↓'):'↕'}</span></button></th>`;
const chips=[['all','Alle'],['running','Laufend'],['stopped','Gestoppt'],['qemu','QEMU'],['lxc','LXC'],['template','Vorlagen']];
return head('','Virtuelle Maschinen','QEMU-VMs und LXC-Container mit Status, Platzierung und Auslastung.',refreshButton()+`<button data-action="create_vm">${icon('plus')} VM erstellen</button><button data-action="create_lxc">${icon('plus')} Container erstellen</button><button data-action="restore_lxc">Container wiederherstellen</button>`+newVmButton())+`<div class="toolbar list-toolbar"><div class="search">${icon('search')}<input id="vm-search" type="search" aria-label="VMs durchsuchen" placeholder="Name, VMID oder Node …" value="${esc(state.query)}"></div><div class="filter-chips" role="group" aria-label="Nach Status oder Typ filtern">${chips.map(([k,l])=>`<button type="button" class="chip ${active===k?'selected':''}" data-vm-filter="${k}" aria-pressed="${active===k}">${l}<span class="chip-count">${all.filter(vmFilters[k]).length}</span></button>`).join('')}</div><span class="toolbar-count">${v.length} von ${all.filter(vmFilters.all).length}</span><button data-action="bulk" ${state.selectedVMs.length?'':'disabled'}>Sammelaktion${state.selectedVMs.length?' ('+state.selectedVMs.length+')':''}</button></div><section class="panel">${v.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="VM-Tabelle"><table class="data-table"><thead><tr><th class="selection-column"><input type="checkbox" class="row-select" data-select-all-vms aria-label="Alle sichtbaren VMs auswählen" ${allSelected?'checked':''} ${selectable.length?'':'disabled'}></th>${th('name','Name')}${th('vmid','VMID','num')}${th('status','Status')}${th('node','Node')}${th('maxcpu','vCPU','num')}${th('cpu','CPU-Last','usage-column')}${th('mem','Arbeitsspeicher','usage-column')}${th('type','Typ')}</tr></thead><tbody>${v.map(v=>{const key=v.connection_id+':'+v.vmid,running=v.status==='running';return `<tr class="${state.selectedVMs.includes(key)?'selected':''}"><td>${['qemu','lxc'].includes(v.type)?`<input type="checkbox" class="row-select" data-select-vm="${esc(v.connection_id)}:${v.vmid}" aria-label="VM ${esc(v.name)} auswählen" ${state.selectedVMs.includes(key)?'checked':''}>`:'—'}</td><td><div class="table-name"><span class="table-symbol">${icon(v.type==='lxc'?'box':'vm')}</span><div>${['qemu','lxc'].includes(v.type)?`<button class="text-button vm-link" data-vm="${esc(v.connection_id)}:${v.vmid}">${esc(v.name||'VM '+v.vmid)}</button>`:`<b>${esc(v.name||'VM '+v.vmid)}</b>`}${state.connections.filter(c=>c.kind!=='pbs').length>1?`<small>${esc(state.connections.find(c=>c.id===v.connection_id)?.name||'')}</small>`:''}</div></div></td><td class="num mono">${esc(v.vmid)}</td><td>${statusTag(v.status)}</td><td>${esc(v.node)}</td><td class="num">${esc(v.maxcpu||0)}</td><td>${running?usageBar((v.cpu||0)*100)+(v.metrics_stale?'<small class="metric-stale">veraltet</small>':''):'<span class="muted">—</span>'}</td><td>${running?usageBar(percent(v.mem||0,v.maxmem||0),fmtBytes(v.mem||0)+' / '+fmtBytes(v.maxmem||0)):`<span class="muted">${fmtBytes(v.maxmem||0)} zugewiesen</span>`}</td><td><span class="type-tag">${v.type==='lxc'?'LXC':'QEMU'}${isTemplate(v)?' · Vorlage':''}</span></td></tr>`}).join('')}</tbody></table></div>`:empty('vm',state.query||active!=='all'?'Keine Treffer':'Noch keine VMs',state.query||active!=='all'?'Suchbegriff oder Filter anpassen.':'Proxmox-Verbindung einrichten oder eine Vorlage aus dem Marketplace bereitstellen.')}</section>`}
function customMarket(){const apps=state.blueprints.filter(b=>(state.category==='Alle'||b.category===state.category)&&(b.name+' '+b.description).toLowerCase().includes(state.query.toLowerCase()));return head('','Marketplace','Eigene VM-Vorlagen mit definierten Ressourcen, Netzwerk und Storage.',`<button class="ghost" data-action="blueprint">${icon('plus')} Blueprint hinzufügen</button>`)+`<div class="toolbar"><div class="search">${icon('search')}<input id="market-search" aria-label="Vorlagen durchsuchen" placeholder="Vorlagen durchsuchen …" value="${esc(state.query)}"></div><div class="filters" role="group" aria-label="Kategorien">${['Alle','Betriebssystem','Container','Datenbanken','Anwendungen'].map(c=>`<button data-category="${c}" class="${c===state.category?'active':''}" aria-pressed="${c===state.category}">${c}</button>`).join('')}</div></div><div class="resultline"><span>${apps.length} ${apps.length===1?'BLUEPRINT':'BLUEPRINTS'}</span><span>${state.mode==='demo'?'DEMO-KATALOG':'EIGENER KATALOG'}</span></div><section class="catalog">${apps.map(b=>`<article class="appcard" style="--app-color:${/^#[a-fA-F0-9]{6}$/.test(b.color||'')?b.color:'#a7dcca'}"><div class="appcard-top"><span class="app-logo">${esc(b.logo||b.name.slice(0,2).toUpperCase())}</span><span class="category">${esc(b.category)}</span></div><h3>${esc(b.name)}</h3><p>${esc(b.description)}</p><div class="tags"><span class="tag">Cloud-init</span><span class="tag">${esc(b.node)} / ${esc(b.template_vmid)}</span></div><div class="appcard-bottom"><span class="mono">${b.cpu} vCPU · ${b.ram} GiB · ${b.disk} GiB</span><button data-configure="${esc(b.id)}">Konfigurieren ${icon('arrow')}</button></div></article>`).join('')}</section>${!apps.length?`<section class="panel">${empty('market',state.query||state.category!=='Alle'?'Keine passenden Blueprints':'Noch keine Blueprints veröffentlicht.',state.query||state.category!=='Alle'?'Ändere die Suche oder Kategorie.':'Verbinde Proxmox und verknüpfe eine vorbereitete Cloud-init-VM als Blueprint.',`<button class="primary" data-action="blueprint">${icon('plus')} Blueprint hinzufügen</button>`)}</section>`:''}${state.mode==='demo'?'<div class="hint warn">Interaktive Demo: Die Vorlagen simulieren den Ablauf. Es werden keine Images heruntergeladen, keine Software installiert und keine echten VMs angelegt.</div>':'<div class="hint">Die Software eines Blueprints muss bereits in der Proxmox-Vorlage installiert sein. Orbit klont die Vorlage und setzt Ressourcen sowie Cloud-init; es führt keine beliebigen Installationsskripte aus.</div>'}`}
function jobs(){const tab=state.jobsTab==='proxmox'?'proxmox':'orbit';return head('','Aufgaben','Orbit-Aktionen mit nachvollziehbaren Schritten und alle Proxmox-Tasks der verbundenen Cluster.',refreshButton())+`<nav class="dashboard-tabs" aria-label="Aufgabenbereiche">${[['orbit','Orbit-Aktionen'],['proxmox','Proxmox-Tasks']].map(([k,l])=>`<button data-jobs-tab="${k}" class="${tab===k?'selected':''}" ${tab===k?'aria-current="page"':''}>${l}</button>`).join('')}</nav>`+(tab==='proxmox'?pveTaskTable():`<section class="panel">${operationTable()}${state.jobs.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Bereitstellungen"><table><thead><tr><th>Bereitstellung</th><th>Status</th><th>Node / VMID</th><th>Erstellt</th><th></th></tr></thead><tbody>${state.jobs.map(j=>`<tr><td><b>${esc(j.name)}</b><div class="small muted">${esc(j.blueprint)}</div></td><td>${statusTag(j.status)}</td><td class="mono">${esc(j.node)} / ${j.vmid}</td><td class="mono muted">${when(j.created)}</td><td><button class="text-button" data-job="${j.id}">Protokoll ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('activity','Keine Aufgaben','Bereitstellungen erscheinen hier mit jedem einzelnen Schritt.',newVmButton())}</section>`)}
const pveTaskTypes={qmstart:'VM starten',qmstop:'VM ausschalten',qmshutdown:'VM herunterfahren',qmreboot:'VM neu starten',qmreset:'VM zurücksetzen',qmsuspend:'VM pausieren',qmresume:'VM fortsetzen',qmigrate:'VM migrieren',qmclone:'VM klonen',qmcreate:'VM erstellen',qmdestroy:'VM löschen',qmtemplate:'In Vorlage umwandeln',qmsnapshot:'Snapshot erstellen',qmrollback:'Snapshot zurückrollen',qmdelsnapshot:'Snapshot löschen',qmmove:'Disk verschieben',qmconfig:'VM-Konfiguration',qmrestore:'VM wiederherstellen',resize:'Disk vergrößern',vzdump:'Backup',vzstart:'CT starten',vzstop:'CT ausschalten',vzshutdown:'CT herunterfahren',vzreboot:'CT neu starten',vzcreate:'CT erstellen',vzdestroy:'CT löschen',vzmigrate:'CT migrieren',vzclone:'CT klonen',vztemplate:'CT in Vorlage umwandeln',vzsnapshot:'CT-Snapshot',vncproxy:'Konsole',vncshell:'Host-Shell',termproxy:'Terminal',srvreload:'Dienst neu laden',srvrestart:'Dienst neu starten',aptupdate:'Paketlisten aktualisieren',download:'Download',imgcopy:'Image kopieren',hamigrate:'HA-Migration',hastart:'HA-Start',hastop:'HA-Stopp',startall:'Alle Gäste starten',stopall:'Alle Gäste stoppen',migrateall:'Alle Gäste migrieren',garbage_collection:'Garbage Collection',verify:'Backup-Prüfung',prune:'Prune',backup:'Backup',reader:'Backup lesen',sync:'Synchronisation'};
function pveTaskState(t){return t.endtime?(t.status==='OK'?'completed':String(t.status||'').startsWith('WARNINGS')?'warning':'failed'):'running'}
function pveTaskDuration(t){const end=t.endtime||Date.now()/1000,sec=Math.max(0,Math.round(end-(t.starttime||end)));return sec<60?sec+' s':sec<3600?Math.floor(sec/60)+' min '+(sec%60)+' s':Math.floor(sec/3600)+' h '+Math.floor(sec%3600/60)+' min'}
function demoPveTasks(){const now=Date.now()/1000,rows=[['pve-01','qmstart','100','root@pam',600,'OK'],['pve-02','vzdump','101','backup@pbs',3600,'OK'],['pve-03','qmigrate','102','root@pam',7200,'OK'],['pve-01','qmsnapshot','103','root@pam',9000,'OK'],['pve-02','vzdump','104','backup@pbs',86400,'ERROR: job failed with err -5 - Input/output error'],['pve-03','aptupdate','','root@pam',90000,'WARNINGS: 1'],['pve-02','qmclone','104','root@pam',30,null]];return rows.map(([node,type,id,user,ago,status],i)=>({upid:`UPID:${node}:0000${(4000+i).toString(16).toUpperCase()}:00100000:${Math.floor(now-ago).toString(16).toUpperCase().padStart(8,'0')}:${type}:${id}:${user}:`,node,type,id,user,starttime:now-ago,endtime:status===null?undefined:now-ago+Math.min(ago-5,40+i*13),status:status===null?undefined:status,connection_id:'demo'}))}
async function loadPveTasks(force=false){const t=state.pveTasks||(state.pveTasks={rows:[],at:0,busy:false,error:''});if(t.busy||(!force&&Date.now()-t.at<4000))return;t.busy=true;try{if(state.mode==='demo'){t.rows=demoPveTasks().sort((a,b)=>(b.starttime||0)-(a.starttime||0));t.error=''}else{const results=await Promise.allSettled(state.connections.map(c=>api('connections/'+encodeURIComponent(c.id)+'/tasks')));t.rows=results.flatMap(r=>r.status==='fulfilled'&&Array.isArray(r.value)?r.value:[]).sort((a,b)=>(b.starttime||0)-(a.starttime||0));const failed=results.filter(r=>r.status==='rejected').length;t.error=failed?failed+' Verbindung(en) konnten keine Tasks liefern.':''}t.at=Date.now()}catch(e){t.error=e.message||'Tasks konnten nicht geladen werden.'}finally{t.busy=false}if(state.page==='jobs'&&state.jobsTab==='proxmox')(typeof renderLive==='function'?renderLive:render)()}
function pveTaskTable(){const t=state.pveTasks||{rows:[]},f=state.taskFilter||'all',q=String(state.taskQuery||'').toLowerCase(),counts={all:t.rows.length,running:0,failed:0};for(const r of t.rows){const s=pveTaskState(r);if(s==='running')counts.running++;if(s==='failed')counts.failed++}const rows=t.rows.filter(r=>f==='all'||pveTaskState(r)===f).filter(r=>!q||[r.node,r.type,pveTaskTypes[r.type],r.id,r.user].some(x=>String(x??'').toLowerCase().includes(q)));const conn=id=>state.connections.find(c=>c.id===id)?.name||id;
return `<div class="toolbar list-toolbar"><div class="search">${icon('search')}<input id="task-search" type="search" aria-label="Tasks durchsuchen" placeholder="Typ, Node, VMID oder Benutzer …" value="${esc(state.taskQuery||'')}"></div><div class="filter-chips" role="group" aria-label="Nach Status filtern">${[['all','Alle'],['running','Laufend'],['failed','Fehlgeschlagen']].map(([k,l])=>`<button type="button" class="chip ${f===k?'selected':''}" data-task-filter="${k}" aria-pressed="${f===k}">${l}<span class="chip-count">${counts[k]}</span></button>`).join('')}</div><span class="toolbar-count">${t.at?'Stand '+new Date(t.at).toLocaleTimeString('de-DE'):t.busy?'Wird geladen …':''}</span></div>${t.error?`<div class="hint warn">${esc(t.error)}</div>`:''}<section class="panel">${rows.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Proxmox-Tasks"><table class="data-table"><thead><tr><th>Start</th><th>Aufgabe</th><th>Ziel</th><th>Node</th><th>Benutzer</th><th class="num">Dauer</th><th>Status</th>${state.connections.length>1?'<th>Verbindung</th>':''}<th></th></tr></thead><tbody>${rows.slice(0,200).map(r=>{const s=pveTaskState(r);return `<tr><td class="num">${r.starttime?when(r.starttime):'—'}</td><td><b>${esc(pveTaskTypes[r.type]||r.type)}</b>${pveTaskTypes[r.type]?`<small class="muted"> · ${esc(r.type)}</small>`:''}</td><td>${r.id?esc(r.id):'<span class="muted">—</span>'}</td><td>${esc(r.node)}</td><td class="muted">${esc(r.user)}</td><td class="num">${pveTaskDuration(r)}</td><td>${s==='running'?statusTag('running'):s==='completed'?statusTag('completed'):s==='warning'?`<span class="status-tag warn"><span class="dot amber"></span>Warnungen</span>`:`<span class="status-tag fail" title="${esc(r.status)}"><span class="dot"></span>Fehler</span>`}</td>${state.connections.length>1?`<td class="muted">${esc(conn(r.connection_id))}</td>`:''}<td><button class="text-button" data-task-log="${esc(r.connection_id)}|${esc(r.node)}|${esc(r.upid)}">Log ${icon('arrow')}</button></td></tr>`}).join('')}</tbody></table></div>`:empty('activity',t.busy?'Tasks werden geladen …':'Keine Tasks',t.busy?'':(f!=='all'||q?'Filter oder Suchbegriff anpassen.':'Proxmox meldet keine aktuellen Tasks.'))}</section>`}
let taskLogEpoch=0;
async function openTaskLog(ref){const[cid,node,upid]=ref.split('|'),row=(state.pveTasks?.rows||[]).find(r=>r.upid===upid)||{type:'',node},epoch=++taskLogEpoch;const title=(pveTaskTypes[row.type]||row.type||'Task')+(row.id?' · '+row.id:'');openModal('PROXMOX-TASK · '+node,title,'<div class="loading">Log wird geladen …</div>');
const show=d=>{if(epoch!==taskLogEpoch||!modal.open)return false;const st=d.status||{},lines=Array.isArray(d.log)?d.log.map(l=>l.t).join('\n'):'',running=st.status==='running',ok=st.exitstatus==='OK';openModal('PROXMOX-TASK · '+node,title,`<div class="task-log-head">${running?statusTag('running'):ok?statusTag('completed'):`<span class="status-tag fail"><span class="dot"></span>${esc(st.exitstatus||'Fehler')}</span>`}<span class="muted mono">${esc(upid)}</span></div><pre class="task-log" tabindex="0">${esc(lines||'Kein Log vorhanden.')}</pre><div class="modal-foot"><span class="muted">${running?'Wird alle 2 Sekunden aktualisiert.':''}</span><button data-cancel>Schließen</button></div>`);const pre=modal.querySelector('.task-log');if(pre)pre.scrollTop=pre.scrollHeight;return running};
const step=async()=>{try{const d=state.mode==='demo'?{status:{status:row.endtime?'stopped':'running',exitstatus:row.status||''},log:[{n:1,t:'task started by '+(row.user||'root@pam')},...(row.type==='vzdump'?[{n:2,t:'INFO: starting new backup job: vzdump '+row.id},{n:3,t:'INFO: creating Proxmox Backup Server archive'}]:[]),...(row.endtime?[{n:9,t:row.status==='OK'?'TASK OK':'TASK '+row.status}]:[])]}:await api('connections/'+encodeURIComponent(cid)+'/tasks/'+encodeURIComponent(node)+'/'+encodeURIComponent(upid));if(show(d))setTimeout(step,2000)}catch(e){if(epoch===taskLogEpoch&&modal.open)openModal('PROXMOX-TASK · '+node,title,`<div class="hint error">${esc(e.message)}</div><div class="modal-foot"><button data-cancel>Schließen</button></div>`)}};step()}
function pageContent(){return({object:objectView,overview,clusters,vms,market,jobs,settings,storage:()=>moduleView('storage'),network:()=>moduleView('network'),protection:()=>moduleView('protection'),security:()=>moduleView('security'),lifecycle:()=>moduleView('lifecycle'),ecosystem,alerts:()=>alertsPage(),drs:()=>drsPage()})[state.page]()}
function render(){if(!state.authenticated)return;$('#app').innerHTML=shell();bind();if(typeof connectLive==='function')connectLive()}
function bind(){bindSettings();if(typeof bindOperations==='function')bindOperations();if(typeof bindConsoleControls==='function')bindConsoleControls();if(typeof bindManagement==='function')bindManagement();if(typeof bindInfrastructure==='function')bindInfrastructure();$$('[data-enable-import]').forEach(b=>b.onclick=()=>enableImport(b.dataset.enableImport));$$('[data-registry-deploy]').forEach(b=>b.onclick=()=>registryDeploy(b.dataset.registryDeploy));const modeButton=$('[data-catalog-mode]');if(modeButton)modeButton.onclick=catalogMode;const navToggle=$('[data-toggle-nav]');if(navToggle)navToggle.onclick=()=>{state.navCollapsed=!state.navCollapsed;render()};$$('[data-catalog-details]').forEach(b=>b.onclick=()=>catalogDetails(b.dataset.catalogDetails));$$('[data-market-tab]').forEach(b=>b.onclick=()=>{state.marketTab=b.dataset.marketTab;render()});const sync=$('[data-catalog-sync]');if(sync)sync.onclick=async()=>{sync.disabled=true;try{if(state.mode==='demo'){toast('Demo: Katalogaktualisierung simuliert.');return}await api('catalog/sync',{method:'POST',body:'{}'});toast('Katalogaktualisierung gestartet.');await refresh()}catch(e){toast(e.message);sync.disabled=false}};$$('[data-select-vm]').forEach(b=>b.onchange=()=>{const key=b.dataset.selectVm;if(b.checked&&state.selectedVMs.length>=20){b.checked=false;toast('Maximal 20 VMs pro Sammelaktion.');return}state.selectedVMs=b.checked?[...state.selectedVMs.filter(k=>k!==key),key]:state.selectedVMs.filter(k=>k!==key);render()});$$('[data-object-tab]').forEach(b=>b.onclick=()=>{if(state.consoleRFB){state.consoleRFB.disconnect();state.consoleRFB=null}state.objectTab=b.dataset.objectTab;render();if(state.objectTab==='console'){openConsole();$('#console-panel')?.scrollIntoView?.({block:'start',behavior:'smooth'})}else window.scrollTo({top:0,behavior:'instant'})});$$('[data-hardware-action]').forEach(b=>b.onclick=()=>hardwareAction(b.dataset.hardwareAction));$$('[data-core-action]').forEach(b=>b.onclick=()=>b.dataset.coreAction==='configure'&&typeof guestEditor==='function'?guestEditor('resources'):vmAction(state.object.vm,b.dataset.coreAction,state.object.config));const scope=$('#compute-scope');if(scope)scope.onchange=()=>{state.scope=scope.value;state.selectedVMs=[];state.query='';render()};$$('[data-vm]').forEach(b=>b.onclick=()=>vmDetails(b.dataset.vm));$$('[data-module-refresh]').forEach(b=>b.onclick=()=>loadModule(b.dataset.moduleRefresh,true));$$('[data-operation]').forEach(b=>b.onclick=()=>operationLog(b.dataset.operation));$$('[data-edit-connection]').forEach(b=>b.onclick=()=>connectionModal(b.dataset.editConnection));$$('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));$$('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action](b));$$('[data-configure]').forEach(b=>b.onclick=()=>configure(b.dataset.configure));$$('[data-job]').forEach(b=>b.onclick=()=>jobModal(b.dataset.job));$$('[data-vm-sort]').forEach(b=>b.onclick=()=>{const key=b.dataset.vmSort,current=state.vmSort||{key:'name',dir:1};state.vmSort={key,dir:current.key===key?-current.dir:1};render()});$$('[data-vm-filter]').forEach(b=>b.onclick=()=>{state.vmFilter=b.dataset.vmFilter;render()});$$('[data-select-all-vms]').forEach(b=>b.onchange=()=>{const keys=visibleVMs().filter(v=>['qemu','lxc'].includes(v.type)).map(v=>v.connection_id+':'+v.vmid);if(b.checked){const merged=[...new Set([...state.selectedVMs,...keys])];if(merged.length>20)toast('Maximal 20 VMs pro Sammelaktion.');state.selectedVMs=merged.slice(0,20)}else state.selectedVMs=state.selectedVMs.filter(k=>!keys.includes(k));render()});$$('[data-jobs-tab]').forEach(b=>b.onclick=()=>{state.jobsTab=b.dataset.jobsTab;render();if(state.jobsTab==='proxmox')loadPveTasks(true)});$$('[data-task-filter]').forEach(b=>b.onclick=()=>{state.taskFilter=b.dataset.taskFilter;render()});$$('[data-task-log]').forEach(b=>b.onclick=()=>openTaskLog(b.dataset.taskLog));$$('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;render()});$$('[data-delete-bp]').forEach(b=>b.onclick=()=>deleteBlueprint(b.dataset.deleteBp));for(const id of ['market-search','vm-search','task-search']){const field=$('#'+id);if(field)field.oninput=()=>{const value=field.value,pos=field.selectionStart;if(id==='task-search')state.taskQuery=value;else state.query=value;render();const next=$('#'+id);next.focus();next.setSelectionRange(pos,pos)}}}
const actions={refresh:async b=>{b.disabled=true;await refresh();toast(state.error?'Abruf mit Fehlern abgeschlossen.':'Daten aktualisiert.')},blueprint:()=>blueprintModal(),connection:()=>connectionModal(),logout:async()=>{try{await api('logout',{method:'POST',body:'{}'});state.authenticated=false;state.user=null;state.account=null;authScreen(true)}catch(e){toast(e.message)}}};
const modal=$('#modal');let modalJob=null,modalOperation=null,modalEpoch=0,modalBusy=false;function closeModal(force=false){if(modalBusy&&force!==true){toast('Anfrage läuft. Bitte auf das Ergebnis warten.');return}modalBusy=false;modalEpoch++;modal.close();modalJob=null;modalOperation=null}function setModalBusy(value){modalBusy=value;modal.querySelectorAll('[data-close],[data-cancel],button[type=submit],button.primary').forEach(b=>b.disabled=value)}function openModal(kicker,title,body){modalEpoch++;modalJob=null;modalOperation=null;modalBusy=false;modal.innerHTML=`<div class="modal-head"><div><div class="eyebrow">${esc(kicker)}</div><h2 id="modal-title">${esc(title)}</h2></div><button class="ghost btn-icon" data-close aria-label="Dialog schließen">${icon('close')}</button></div><div class="modal-body">${body}</div>`;modal.querySelector('[data-close]').onclick=closeModal;modal.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=closeModal);if(!modal.open)modal.showModal()}
modal.addEventListener('close',()=>{modalJob=null;modalOperation=null;modalBusy=false});modal.addEventListener('cancel',e=>{if(modalBusy)e.preventDefault()});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function field(label,name,value='',opts={}){return `<div class="${opts.full?'full':''}"><label for="f-${name}">${label}</label>${opts.textarea?`<textarea id="f-${name}" name="${name}" rows="3" ${opts.optional?'':'required'}>${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" value="${esc(value)}" type="${opts.type||'text'}" ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.max!==undefined?`max="${opts.max}"`:''} ${opts.pattern?`pattern="${opts.pattern}"`:''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''} ${opts.optional?'':'required'} ${opts.autocomplete?`autocomplete="${opts.autocomplete}"`:''}>`}${opts.help?`<div class="field-help">${opts.help}</div>`:''}</div>`}
// A selectable empty option ("Ohne ISO", "ISO auswerfen") is a valid choice, so such selects must not be required.
function selectField(label,name,options){const emptyChoice=/<option value=""(?![^>]*disabled)[^>]*>/.test(options);return `<div><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${emptyChoice?'':'required'}>${options}</select></div>`}
const option=(value,label,selected=false)=>`<option value="${esc(value)}" ${selected?'selected':''}>${esc(label)}</option>`;
const formError=msg=>{const el=modal.querySelector('[data-form-error]');if(el){el.textContent=msg;el.setAttribute('role','alert')}};
function configure(id){const bp=state.blueprints.find(b=>b.id===id);if(!bp)return;const requestKey=newRequestKey();openModal('DEPLOY / '+(state.mode==='demo'?'SIMULATION':'PROXMOX'),bp.name,`<form id="deploy-form"><p>Aus einer festen Vorlage. Ressourcen und SSH-Zugang werden pro VM festgelegt.</p><div class="summary"><div><span>ZIEL-NODE</span><b>${esc(bp.node)}</b></div><div><span>STORAGE</span><b>${esc(bp.storage)}</b></div><div><span>NETZWERK / DHCP</span><b>${esc(bp.bridge)}</b></div></div>${field('VM-Name','name','',{pattern:'[a-zA-Z][a-zA-Z0-9\\-]{0,62}',placeholder:'docker-prod-02',help:'Beginnt mit einem Buchstaben; bis zu 63 Zeichen, Ziffern und Bindestriche.'})}<div class="formgrid">${field('vCPU','cpu',bp.cpu,{type:'number',min:1,max:128})}${field('RAM · GiB','ram',bp.ram,{type:'number',min:1,max:1024})}${field('Systemlaufwerk · GiB','disk',bp.disk,{type:'number',min:bp.min_disk,max:65536,help:'Mindestens '+bp.min_disk+' GiB. Vergrößern, nicht verkleinern.'})}${field('Cloud-init-Benutzer','username',bp.username,{optional:true})}</div><label for="f-ssh">Öffentlicher SSH-Schlüssel</label><textarea id="f-ssh" name="ssh" placeholder="ssh-ed25519 AAAA…" maxlength="16384"></textarea><div class="field-help">Nur öffentliche Schlüssel. Ohne Schlüssel bleibt der in der Vorlage vorbereitete Zugriff bestehen.</div><label class="checkbox"><input type="checkbox" name="start" checked> VM nach der Konfiguration starten</label><div class="hint ${state.mode==='demo'?'warn':''}">${state.mode==='demo'?'Demo: keine echte VM und keine Softwareinstallation.':'Es wird ein vollständiger Klon erzeugt. Die VM erhält DHCP am festgelegten Netzwerk. Vorlagen müssen passende Cloud-init- und Gastunterstützung mitbringen.'}</div><div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary" type="submit">${icon('plus')} ${state.mode==='demo'?'Demo-Bereitstellung starten':'VM jetzt erstellen'}</button></div></form>`);$('#f-username').readOnly=true;$('#deploy-form').onsubmit=async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),button=f.querySelector('[type=submit]');const payload={blueprint_id:id,request_key:requestKey,name:d.name,cpu:+d.cpu,ram:+d.ram,disk:+d.disk,ssh:d.ssh,start:f.elements.start.checked};button.disabled=true;setModalBusy(true);formError('');try{let job;if(state.mode==='demo'){if(state.resources.some(r=>r.name===d.name)||demoStore.jobs.some(j=>j.name===d.name))throw new Error('Dieser VM-Name wird bereits verwendet.');job={id:newRequestKey(),name:d.name,blueprint:bp.name,node:bp.node,vmid:200+demoStore.jobs.length,cpu:+d.cpu,ram:+d.ram,disk:+d.disk,start:payload.start,status:'running',stage:'clone_wait',created:Date.now()/1000,events:[{at:Date.now()/1000,message:'Demo: Bereitstellung eingeplant.'}]};demoStore.jobs.unshift(job);saveDemo();setTimeout(()=>advanceDemo(job.id,1),1300);setTimeout(()=>advanceDemo(job.id,2),2900)}else{job=await api('jobs',{method:'POST',body:JSON.stringify(payload)});state.jobs=[job,...state.jobs.filter(j=>j.id!==job.id)]}closeModal(true);await refresh(false);nav('jobs');jobModal(job.id);toast(state.mode==='demo'?'Simulation gestartet.':'Bereitstellung eingeplant.')}catch(e){setModalBusy(false);formError(e.message);button.disabled=false}}}
function advanceDemo(id,step){const j=demoStore.jobs.find(j=>j.id===id);if(!j)return;j.events.push({at:Date.now()/1000,message:step===1?'Demo: Klon erstellt. Cloud-init und Ressourcen konfiguriert.':'Demo abgeschlossen. Keine echte VM wurde angelegt.'});if(step===2){j.status='completed';j.stage='done'}saveDemo();loadDemo();if(state.authenticated)render();if(modalJob===id)jobModal(id,true)}
function jobModal(id,update=false){const j=state.jobs.find(j=>j.id===id);if(!j)return;const content=`<div style="margin-top:20px">${statusTag(j.status)}</div><div class="summary"><div><span>VMID / NODE</span><b>${j.vmid} / ${esc(j.node)}</b></div><div><span>RESSOURCEN</span><b>${j.cpu} vCPU · ${j.ram} GiB · ${j.disk} GiB</b></div></div><div class="progress ${['queued','running'].includes(j.status)?'running':['failed','needs_attention'].includes(j.status)?'error':''}"><i></i></div><div style="margin-top:20px">${j.events.map(e=>`<div class="job-event"><time>${new Date(e.at*1000).toLocaleTimeString('de-DE')}</time><p>${esc(e.message)}</p></div>`).join('')}</div>${['failed','needs_attention'].includes(j.status)?'<div class="hint warn">Die VM wird nicht automatisch gelöscht. Prüfe die VMID und das Aufgabenprotokoll in Proxmox, bevor du eine neue Bereitstellung startest.</div>':''}<div class="modal-foot"><span class="mono muted">${state.mode==='demo'?'SIMULATION':'PERSISTENTE AUFGABE'}</span><button type="button" data-cancel>Schließen</button></div>`;if(update){modal.querySelector('.modal-body').innerHTML=content;modal.querySelector('[data-cancel]').onclick=closeModal}else openModal('BEREITSTELLUNG',j.name,content);modalJob=id}
function connectionModal(editId=null){const existing=state.connections.find(c=>c.id===editId);if(state.mode==='demo'){openModal('LOKALER BETRIEB','Proxmox bleibt im eigenen Netzwerk.',`<p style="margin-top:20px">Die gehostete Vorschau ist eine Demo. Echte Verbindungen richtest du in der lokalen Docker-Version ein. Trage hier keine echten API-Tokens ein.</p><div class="steps"><div class="step"><span class="step-number">01</span><div><b>Docker-Version starten</b><p>Compose-Datei und Installationsanleitung sind im Projekt enthalten.</p></div></div><div class="step"><span class="step-number">02</span><div><b>Einrichtungscode & Passwort</b><p>Einmalcode aus dem Datenvolume lesen und Administratorpasswort setzen.</p></div></div><div class="step"><span class="step-number">03</span><div><b>Host verbinden</b><p>Adresse und Token im lokalen Einrichtungsdialog hinterlegen.</p></div></div></div><div class="modal-foot"><button data-cancel>Verstanden</button></div>`);return}openModal('VERBINDUNG EINRICHTEN',existing?'Verbindung bearbeiten':'Proxmox verbinden',`<form id="connection-form"><p>Verbindung wird vor dem Speichern mit aktivierter TLS-Prüfung getestet.</p>${existing?'':selectField('Verbindungstyp','kind',option('pve','Proxmox VE')+option('pbs','Proxmox Backup Server'))}${field('Name','name',existing?.name||'',{placeholder:'Homelab / Frankfurt'})}${field('Proxmox-HTTPS-Adresse','url',existing?.url||'',{type:'url',placeholder:'https://pve.example:8006'})}${field('Weitere Node-Adressen (optional, eine je Zeile)','endpoints',(existing?.endpoints||[]).join('\n'),{textarea:true,optional:true,help:'Nur Nodes desselben VE-Clusters. Bei Ausfall wechselt Orbit für Lesezugriffe automatisch. Kein PDM erforderlich.'})}${field('API-Token','token','',{type:'password',optional:!!existing,placeholder:existing?'Leer lassen, um Token zu behalten':'orbit@pve!console=…',autocomplete:'off',help:'Format für VE und PBS in Orbit: Benutzer@Realm!Token-ID=Secret. Der Dienst setzt den passenden API-Header. Kein Root-Passwort verwenden.'})}<div class="hint">Bei eigener CA das Zertifikat im Container einbinden und ORBIT_CA_FILE setzen. Das Zertifikat muss zur Hostadresse passen.</div><div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary">Verbindung testen & speichern</button></div></form>`);$('#connection-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]')||e.target.querySelector('.primary');button.disabled=true;setModalBusy(true);formError('');try{await api(existing?'connections/'+existing.id:'connections',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal(true);await refresh();toast('Proxmox-Verbindung gespeichert.')}catch(e){setModalBusy(false);formError(e.message);button.disabled=false}}}
async function blueprintModal(){if(!state.connections.some(c=>c.kind!=='pbs')){toast('Bitte zuerst Proxmox VE verbinden.');nav('settings');return}if(state.mode==='demo'){openBlueprintForm([{vmid:9000,name:'ubuntu-cloud-template',node:'pve-01'}],[{node:'pve-01',storages:['ceph-pool','local-lvm'],bridges:['vmbr0','vmbr1']}],state.connections[0].id);return}openModal('SERVICEKATALOG','Vorlage auswählen',`<p style="margin-top:20px">Proxmox-Verbindung mit der Cloud-init-Vorlage auswählen.</p><form id="pick-connection">${selectField('Verbindung','connection',state.connections.filter(c=>c.kind!=='pbs').map(c=>option(c.id,c.name)).join(''))}<div data-form-error class="hint error"></div><div class="modal-foot"><button data-cancel type="button">Abbrechen</button><button class="primary">Vorlagen laden ${icon('arrow')}</button></div></form>`);$('#pick-connection').onsubmit=async e=>{e.preventDefault();const cid=e.target.elements.connection.value,button=e.target.querySelector('.primary');button.disabled=true;setModalBusy(true);try{const [templates,targets]=await Promise.all([api('connections/'+cid+'/templates'),api('connections/'+cid+'/targets')]);if(!templates.length)throw new Error('Keine QEMU-Vorlagen gefunden. In Proxmox eine VM mit Cloud-init als Vorlage vorbereiten.');openBlueprintForm(templates,targets,cid)}catch(e){setModalBusy(false);formError(e.message);button.disabled=false}}}
function openBlueprintForm(templates,targets,cid){openModal('BLUEPRINT VERÖFFENTLICHEN','Aus Vorlage wird Service.',`<form id="blueprint-form"><p>Software muss bereits in der Vorlage eingerichtet sein. Orbit prüft Vorlagenstatus, Cloud-init-Laufwerk und Disk-Größe.</p>${selectField('Proxmox-Vorlage','template',templates.map(t=>option(t.vmid,t.name+' / '+t.node+' / '+t.vmid)).join(''))}<div class="formgrid">${field('Name im Marketplace','name','',{placeholder:'Ubuntu Server'})}${selectField('Kategorie','category',['Betriebssystem','Container','Datenbanken','Anwendungen'].map(c=>option(c,c)).join(''))}</div><label for="f-description">Beschreibung</label><textarea id="f-description" name="description" maxlength="500" required placeholder="Was ist in dieser Vorlage vorbereitet?"></textarea><div class="formgrid">${selectField('Storage','storage','')}${selectField('Netzwerk-Bridge','bridge','')}${field('Standard-vCPU','cpu',2,{type:'number',min:1,max:128})}${field('Standard-RAM · GiB','ram',4,{type:'number',min:1,max:1024})}${field('Standard-Disk · GiB','disk',32,{type:'number',min:8,max:65536})}${field('Systemlaufwerk','disk_device','scsi0',{pattern:'(scsi|virtio|sata)[0-9]+'})}${field('Cloud-init-Benutzer','username','orbit',{pattern:'[a-zA-Z_][a-zA-Z0-9_\\-]*'})}</div><div class="hint">Ziel-Node ist der Node der Vorlage. Die Standard-Disk darf nicht kleiner als das Vorlagenlaufwerk sein.</div><div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary">${icon('plus')} Blueprint veröffentlichen</button></div></form>`);function updateTargets(){const node=templates.find(t=>String(t.vmid)===$('#f-template').value)?.node,target=targets.find(t=>t.node===node);$('#f-storage').innerHTML=(target?.storages||[]).map(s=>option(s,s)).join('');$('#f-bridge').innerHTML=(target?.bridges||[]).map(s=>option(s,s)).join('')}$('#f-template').onchange=updateTargets;updateTargets();$('#blueprint-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),button=e.target.querySelector('.primary');button.disabled=true;const payload={...d,connection_id:cid,node:templates.find(t=>String(t.vmid)===d.template).node,template_vmid:+d.template,cpu:+d.cpu,ram:+d.ram,disk:+d.disk};delete payload.template;setModalBusy(true);try{if(state.mode==='demo'){if(payload.disk<16)throw new Error('Die Demo-Vorlage benötigt mindestens 16 GiB.');demoStore.blueprints=[...state.blueprints,{...payload,id:newRequestKey(),min_disk:16,logo:payload.name.slice(0,2).toUpperCase()}];saveDemo()}else await api('blueprints',{method:'POST',body:JSON.stringify(payload)});closeModal(true);await refresh(false);nav('market');toast('Blueprint im Marketplace veröffentlicht.')}catch(e){setModalBusy(false);formError(e.message);button.disabled=false}}}
function deleteBlueprint(id){const bp=state.blueprints.find(b=>b.id===id);if(!bp)return;openModal('KATALOG VERWALTEN','Blueprint entfernen?',`<p style="margin-top:20px">„${esc(bp.name)}“ aus dem Marketplace entfernen? Die Proxmox-Vorlage und vorhandene VMs bleiben erhalten.</p><div data-form-error class="hint error"></div><div class="modal-foot"><button data-cancel>Abbrechen</button><button class="danger" id="confirm-delete">Blueprint entfernen</button></div>`);$('#confirm-delete').onclick=async e=>{e.target.disabled=true;setModalBusy(true);try{if(state.mode==='demo'){demoStore.blueprints=state.blueprints.filter(b=>b.id!==id);saveDemo()}else await api('blueprints/'+id,{method:'DELETE'});closeModal(true);await refresh();toast('Blueprint entfernt.')}catch(e){setModalBusy(false);formError(e.message);e.target.disabled=false}}}
function authScreen(configured){$('#app').innerHTML=`<div class="auth-page"><div class="auth-box"><div class="logo"><span class="brandmark">◉</span> orbit</div><div class="eyebrow">LOKALER WORKSPACE</div><h1>${configured?'Willkommen zurück.':'Orbit einrichten'}</h1><p>${configured?'Mit Benutzername und Passwort anmelden.':'Einmalcode aus /data/setup-token im Container lesen und ein Administratorpasswort festlegen.'}</p><form id="auth-form">${configured?field('Benutzername','username','admin',{autocomplete:'username'}):field('Einrichtungscode','token','',{type:'password',autocomplete:'off'})}${field(configured?'Passwort':'Administratorpasswort','password','',{type:'password',autocomplete:configured?'current-password':'new-password',help:configured?'':'Mindestens 12 Zeichen.'})}${configured?'':field('Passwort wiederholen','repeat','',{type:'password',autocomplete:'new-password'})}${configured?`<div id="auth-code" hidden>${field('Code aus der Authenticator-App','code','',{autocomplete:'one-time-code',optional:true,placeholder:'123456'})}</div>`:''}<div class="hint error" id="auth-error" role="alert"></div><button class="primary">${icon('lock')}${configured?'Workspace öffnen':'Workspace einrichten'}</button></form>${configured&&state.sso?`<div class="sso-divider"><span>oder</span></div><a class="sso-button" href="/api/oidc/login">${icon('server')} ${esc(state.sso.label)}</a>`:''}</div></div>`;{const m=typeof location!=='undefined'&&location.hash.match(/sso-error=([^&]+)/);if(m){$('#auth-error').textContent=decodeURIComponent(m[1].replace(/\+/g,' '));history.replaceState(null,'',location.pathname)}}$('#auth-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),button=e.target.querySelector('button');if(!configured&&(data.password.length<12||data.password!==data.repeat)){$('#auth-error').textContent='Passwörter müssen übereinstimmen und mindestens 12 Zeichen enthalten.';return}button.disabled=true;try{if(!data.code)delete data.code;const response=await fetch('/api/'+(configured?'login':'setup'),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await response.json().catch(()=>({}));if(result.totp_required){$('#auth-code').hidden=false;$('#f-code').required=true;$('#f-code').focus();$('#auth-error').textContent=result.error;button.disabled=false;return}if(!response.ok)throw new Error(result.error||'Anmeldung fehlgeschlagen.');state.csrf=result.csrf;state.authenticated=true;try{state.user=(await api('auth')).user||null}catch{}state.account=null;await refresh(false);render()}catch(err){$('#auth-error').textContent=err.message;button.disabled=false}}}
async function boot(){if(document.querySelector('meta[name="orbit-mode"]').content==='demo'){state.mode='demo';state.authenticated=true;loadDemo();render();for(const job of demoStore.jobs.filter(j=>['running','queued'].includes(j.status)))setTimeout(()=>advanceDemo(job.id,2),1800);return}state.mode='live';try{await api('health');const auth=await api('auth');state.csrf=auth.csrf;state.authenticated=auth.authenticated;state.user=auth.user||null;state.sso=auth.sso||null;if(!auth.authenticated){authScreen(auth.configured);return}await refresh(false);render()}catch(e){$('#app').innerHTML=`<div class="auth-page"><div class="auth-box"><div class="eyebrow">VERBINDUNG UNTERBROCHEN</div><h1>Workspace nicht erreichbar.</h1><p>${esc(e.message)}</p><button class="primary" id="retry-boot">Erneut versuchen</button></div></div>`;$('#retry-boot').onclick=boot}}

// Management modules. Each result is explicitly read-only or backed by a durable operation.
const moduleDescriptions={storage:'Storage-Konfiguration und belegte Kapazität pro Host.',network:'Netzwerk-Interfaces und Bridges der verbundenen VE-Hosts.',protection:'Backup-Zeitpläne, Replikation, HA-Ressourcen und PBS-Datastores.',security:'Lesende Übersicht von Cluster-Firewall und SDN-Netzwerken.',lifecycle:'Verfügbare Pakete und installierte Softwarestände aus Proxmox.'};
const operationLabels={lxc_create:'Container erstellen',lxc_restore:'Container wiederherstellen',guest_edit:'Gastkonfiguration bearbeiten',storage_config:'Storage konfigurieren',infrastructure:'Netzwerk / Firewall',registry_deploy:'Registry-Paket bereitstellen',ha:'HA verwalten',create:'VM erstellen',restore:'Backup wiederherstellen',disk_add:'Laufwerk hinzufügen',disk_resize:'Laufwerk vergrößern',nic:'Netzwerkkarte',metadata:'Name & Optionen',iso:'ISO / Bootmedium',rollback:'Snapshot zurückrollen',snapshot_delete:'Snapshot löschen',delete:'VM löschen',start:'Starten',shutdown:'Herunterfahren',reboot:'Neustarten',stop:'Hart ausschalten',reset:'Zurücksetzen',suspend:'Pausieren',resume:'Fortsetzen',clone:'Klonen',template:'In Vorlage umwandeln',snapshot:'Snapshot erstellen',backup:'Backup erstellen',migrate:'Migrieren',configure:'CPU / RAM ändern'};
function moduleTable(headers,rows,label='Übersicht'){return rows.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="${esc(label)}"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="inline-empty">Keine Einträge in dieser Ansicht.</div>`}
function readPanel(title,result,headers,mapper){return `<section class="panel module-panel"><div class="panel-title"><h2>${esc(title)}</h2><span class="badge">Lesend</span></div>${!result?'<div class="inline-empty">Nicht geladen.</div>':!result.ok?`<div class="hint error">${esc(result.error)}</div>`:moduleTable(headers,(Array.isArray(result.data)?result.data:[]).map(mapper),title)}</section>`}
function demoModule(section){const ok=data=>({ok:true,data});if(section==='storage')return{storage_config:ok([{storage:'ceph-pool',type:'rbd',content:'images,rootdir',shared:1},{storage:'pbs-backup',type:'pbs',content:'backup',shared:1}]),storage_resources:ok(['pve-01','pve-02','pve-03'].map(node=>({node,storage:'ceph-pool',disk:3.6*1024*GiB,maxdisk:12*1024*GiB,status:'available'})))};if(section==='network')return{nodes:['pve-01','pve-02','pve-03'].map(node=>({node,interfaces:ok([{iface:'vmbr0',type:'bridge',active:1,address:'10.20.0.'+(Number(node.at(-1))+10),cidr:'10.20.0.0/24',bridge_ports:'eno1'},{iface:'vmbr1',type:'bridge',active:1,bridge_ports:'eno2'}])}))};if(section==='protection')return{backup_jobs:ok([{id:'nightly',schedule:'02:00',storage:'pbs-backup',enabled:1,mode:'snapshot'}]),replication:ok([{id:'101-0',target:'pve-02',schedule:'*/15',disable:0}]),ha:ok([{type:'service',sid:'vm:101',node:'pve-01',status:'started'}])};if(section==='security')return{firewall_options:ok({enable:1,policy_in:'DROP',policy_out:'ACCEPT'}),firewall_rules:ok([{pos:0,type:'in',action:'ACCEPT',proto:'tcp',dport:'22',source:'10.20.0.0/24',enable:1,comment:'Administrationsnetz'}]),vnets:ok([{vnet:'production',zone:'simple-zone',tag:120}])};if(section==='lifecycle')return{nodes:['pve-01','pve-02','pve-03'].map(node=>({node,updates:ok(node==='pve-02'?[{Package:'proxmox-ve',OldVersion:'Beispielbestand',Version:'Beispielupdate',Title:'Beispiel für ein verfügbares Paket'}]:[]),versions:ok([{Package:'pve-manager',Version:'Beispielversion'},{Package:'proxmox-kernel',Version:'Beispielkernel'}])}))};return{}}
async function loadModule(section,force=false){if(state.moduleBusy[section])return;if(state.modules[section]&&!force)return;state.moduleBusy[section]=true;if(state.page===section)render();try{if(state.mode==='demo'){state.modules[section]=[{connection:{id:'demo',name:'Homelab / Frankfurt',kind:'pve'},data:demoModule(section)}];if(section==='protection')state.modules[section].push({connection:{id:'demo-pbs',name:'Backup-Server / Frankfurt',kind:'pbs'},data:{datastores:{ok:true,data:[{store:'backup-main',total:8*1024*GiB,used:2.3*1024*GiB,avail:5.7*1024*GiB}]},pbs_tasks:{ok:true,data:[]}}})}else{const connections=state.connections.filter(c=>c.kind!=='pbs'||section==='protection');state.modules[section]=await Promise.all(connections.map(async connection=>{try{return{connection,data:await api('connections/'+connection.id+'/modules/'+section)}}catch(e){return{connection,error:e.message}}}))}state.modules[section].at=Date.now()}finally{state.moduleBusy[section]=false;if(state.page===section&&state.authenticated)render()}}
function moduleView(section){if(section==='network'||section==='security')return infrastructurePage(section==='security'?'firewall':'network');const groups=state.modules[section];let body='';if(state.moduleBusy[section]&&!groups)body='<section class="panel"><div class="loading">Daten werden von den verbundenen Systemen geladen …</div></section>';else if(!groups?.length)body=`<section class="panel">${empty('server','Keine passende Verbindung','Verbinde Proxmox VE oder für Datensicherung einen Proxmox Backup Server.',`<button data-nav="settings">Verbindung einrichten</button>`)}</section>`;else body=groups.map(({connection:c,data:d,error})=>`<div class="module-connection"><h2>${esc(c.name)}</h2><span class="badge">${c.kind==='pbs'?'Proxmox Backup Server':'Proxmox VE'}</span></div>${error?`<div class="hint error">${esc(error)}</div>`:moduleBody(section,c,d)}`).join('');const note=section==='lifecycle'?'Diese Ansicht liest den APT-Paketcache und installierte Versionen. Sie installiert keine Updates und startet keine Hosts neu. Firmware und Major-Upgrades brauchen eine geprüfte, herstellerspezifische Integration.':section==='security'?'Firewall und SDN werden lesend angezeigt. Das ersetzt keine Flow-Microsegmentierung; Regeln werden hier noch nicht geändert.':section==='protection'?'Backup- und Snapshot-Aktionen findest du an der jeweiligen VM. HA und Replikation werden überwacht; automatisierte DR-Failover- und Failback-Pläne sind noch nicht implementiert.':'';return head('',pageTitles[section],moduleDescriptions[section],`<button data-module-refresh="${section}" ${state.moduleBusy[section]?'disabled':''}>${icon('refresh')} ${state.moduleBusy[section]?'Lädt …':'Aktualisieren'}</button>`)+`${groups?.at?`<div class="section-meta">Modul zuletzt abgerufen: ${new Date(groups.at).toLocaleTimeString('de-DE')}</div>`:''}${body}${note?`<div class="hint">${note}</div>`:''}${state.mode==='demo'?'<div class="hint warn">Beispieldaten. Alle Einträge in dieser Ansicht sind simuliert.</div>':''}`}
function moduleBody(section,c,d){const val=v=>esc(v??'—');if(c.kind==='pbs')return readPanel('PBS-Datastores',d.datastores,['Datastore','Status','Belegt','Gesamt','Verfügbar'],r=>[val(r.store),r.error?`<span class="status-tag fail">${val(r.error)}</span>`:'Lesbar',Number.isFinite(r.used)?fmtBytes(r.used):'—',Number.isFinite(r.total)?fmtBytes(r.total):'—',Number.isFinite(r.avail)?fmtBytes(r.avail):'—'])+readPanel('PBS-Aufgaben',d.pbs_tasks,['Typ','Start','Status'],r=>[val(r.worker_type||r.type),r.starttime?when(r.starttime):'—',val(r.status||r.state||'laufend')]);if(section==='storage')return (typeof storagePanels==='function'?storagePanels(c,d):readPanel('Storage-Konfiguration',d.storage_config,['Storage','Backend','Inhalte','Shared','Cloud-Image-Import'],r=>[val(r.storage),val(r.type),val(r.content),r.shared?'Ja':'Nein',String(r.content||'').split(',').includes('import')?'<span class="status-tag">Aktiv</span>':['dir','nfs','cifs','cephfs','glusterfs'].includes(r.type)?`<button class="text-button" data-enable-import="${esc(c.id)}:${esc(r.storage)}">Import freigeben</button>`:'Nicht unterstützt'])+readPanel('Kapazität pro Host',d.storage_resources,['Storage','Host','Belegt','Gesamt','Nutzung'],r=>[val(r.storage),val(r.node),fmtBytes(r.disk||0),fmtBytes(r.maxdisk||0),percent(r.disk,r.maxdisk)+' %']));if(section==='network')return d.nodes.map(n=>readPanel('Interfaces / '+n.node,n.interfaces,['Interface','Typ','Aktiv','Adresse / CIDR','Bridge-Ports'],r=>[val(r.iface),val(r.type),r.active?'Ja':'Nein',val(r.cidr||r.address),val(r.bridge_ports)])).join('');if(section==='protection')return (typeof backupJobsPanel==='function'?backupJobsPanel(c,d.backup_jobs):readPanel('Backup-Zeitpläne',d.backup_jobs,['ID','Zeitplan','Storage','Modus','Aktiv'],r=>[val(r.id),val(r.schedule),val(r.storage),val(r.mode),r.enabled===0?'Nein':'Ja']))+readPanel('Replikationsjobs',d.replication,['ID','Ziel','Zeitplan','Aktiv'],r=>[val(r.id),val(r.target),val(r.schedule),r.disable?'Nein':'Ja'])+readPanel('HA-Zustand',d.ha,['Ressource','Typ','Node','Status'],r=>[val(r.sid||r.id),val(r.type),val(r.node),val(r.status)]);if(section==='security'){const f=d.firewall_options;return `<section class="panel module-panel"><div class="panel-title"><h2>Cluster-Firewall</h2><span class="badge">Lesend</span></div>${f?.ok?`<div class="config-strip"><div><span>Aktiviert</span><b>${f.data.enable?'Ja':'Nein'}</b></div><div><span>Eingehend</span><b>${val(f.data.policy_in||'Standard')}</b></div><div><span>Ausgehend</span><b>${val(f.data.policy_out||'Standard')}</b></div></div>`:`<div class="hint error">${val(f?.error||'Nicht geladen')}</div>`}</section>`+readPanel('Cluster-Regeln',d.firewall_rules,['Position','Richtung','Aktion','Protokoll','Port','Quelle','Aktiv'],r=>[val(r.pos),val(r.type),val(r.action),val(r.proto),val(r.dport),val(r.source),r.enable?'Ja':'Nein'])+readPanel('SDN / VNets',d.vnets,['VNet','Zone','Tag'],r=>[val(r.vnet),val(r.zone),val(r.tag)])}if(section==='lifecycle')return d.nodes.map(n=>readPanel('Verfügbare Updates / '+n.node,n.updates,['Paket','Installiert','Verfügbar','Beschreibung'],r=>[val(r.Package),val(r.OldVersion),val(r.Version),val(r.Title||r.Description)])+readPanel('Softwarestand / '+n.node,n.versions,['Paket','Version'],r=>[val(r.Package),val(r.Version)])).join('');return''}
function ecosystem(){const rows=[['Compute','Proxmox VE','VM-Erstellung, Hardware/NICs, CPU/RAM, Start/Shutdown, Snapshots/Rollback, Backup/Restore und Migration','Implementiert'],['Konsole','noVNC + eigenes Gateway','Eingebettet, sitzungsgebunden, TLS-geprüft. Reale VE-Kompatibilität noch abzunehmen.','Integration offen'],['Multi-Cluster','Direkte VE-Verbindungen','Eine Verbindung pro Cluster; aggregiertes Inventar und clusterbezogene Aktionen','Implementiert'],['Datensicherung','PVE vzdump + PBS','VM-Backups und Restore in neue VMID; PBS-Datastores und Aufgaben lesen','Implementiert'],['Netzwerk','VE-Bridges / SDN','Linux-Bridges, Bonds und VLANs bearbeiten; explizit anwenden. VNets ansehen.','Teilweise'],['Sicherheit','PVE Firewall','Datacenter-, Host- und Gastregeln sowie Optionen bearbeiten. Spezialobjekte noch offen.','Teilweise'],['HA / DR','PVE HA und Replikation','Konfiguration ansehen; keine orchestrierten Failover-Pläne','Lesend'],['Lifecycle','Proxmox APT','Paketstände und verfügbare Updates lesen; keine Installation','Lesend'],['Kubernetes','k3s / Kubernetes','Vorbereitete Node-VM über Marketplace klonen; kein NKP-Cluster-Lifecycle','Vorlagenbasiert'],['Files / Objects','NAS / S3-Anbieter','Erfordert eigene Provisionierungs-, Rechte- und Lifecycle-Integration','Offen'],['Volumes','Storage-Backend','Storage-Konfiguration und Gastvolumes bearbeiten; externe Block-Volume-Dienste sind nicht integriert.','Teilweise'],['Firmware','Redfish / Hersteller-API','Kein Firmware-Update-Workflow und keine Hardware-Kompatibilitätsprüfung','Offen'],['Cluster-Anbindung','Direkt an Proxmox VE','Kein PDM benötigt. Mehrere geprüfte API-Endpunkte je Cluster mit Lese-Failover.','Implementiert']];return head('','Integrationen','Umfang dieser Version und Abgrenzung zu einer vollständigen Nutanix-Plattform.')+`<section class="panel">${moduleTable(['Bereich','Anbindung','Funktionsumfang','Stand'],rows.map(([a,b,c,d])=>[esc(a),esc(b),esc(c),`<span class="status-tag ${d==='Implementiert'?'':d==='Offen'?'neutral':'warn'}">${d}</span>`]),'Integrationsumfang')}</section><div class="hint">Diese Übersicht beschreibt implementierte Schnittstellen und offene Integrationen. Sie ist keine Zusage vollständiger Prism-, Files-, Objects-, Flow-, NKP- oder DR-Funktionsgleichheit.</div>`}
function operationTable(){return `<div class="table-toolbar"><h2>Verwaltungsaktionen</h2><span class="small muted">Start · Snapshot · Backup · Migration · Konfiguration</span></div>${moduleTable(['VM / Aktion','Status','Node / VMID','Erstellt','Details'],state.operations.map(o=>[`${esc(o.name)}<div class="small muted">${esc(operationLabels[o.action]||o.action)}</div>`,statusTag(o.status),['infrastructure','storage_config'].includes(o.action)?esc(o.args?.target||o.storage||o.name):esc(o.node)+' / '+o.vmid,when(o.created),`<button class="text-button" data-operation="${esc(o.id)}">Protokoll</button>`]),'Verwaltungsaktionen')}<div class="table-toolbar"><h2>Marketplace-Bereitstellungen</h2></div>`}
function operationLog(id){const o=state.operations.find(o=>o.id===id);if(!o)return;openModal('VERWALTUNGSAKTION',o.name,`<div class="config-strip"><div><span>Aktion</span><b>${esc(operationLabels[o.action])}</b></div><div><span>${['infrastructure','storage_config'].includes(o.action)?'Ziel':'VMID'}</span><b>${esc(['infrastructure','storage_config'].includes(o.action)?(o.args?.target||o.storage||o.name):o.vmid)}</b></div><div><span>Status</span>${statusTag(o.status)}</div></div>${o.events.map(e=>`<div class="job-event"><time>${new Date(e.at*1000).toLocaleTimeString('de-DE')}</time><p>${esc(e.message)}</p></div>`).join('')}${o.status==='needs_attention'?'<div class="hint warn">Den tatsächlichen Zustand in Proxmox prüfen. Orbit wiederholt die Aktion nicht automatisch.</div>':''}<div class="modal-foot"><button data-cancel>Schließen</button><button id="refresh-operation">${icon('refresh')} Aktualisieren</button>${o.status==='needs_attention'?`<button id="review-operation">Prüfung dokumentieren</button>`:''}</div>`);$('#refresh-operation').onclick=async e=>{e.target.disabled=true;const epoch=modalEpoch;await refresh(false);if(modal.open&&epoch===modalEpoch)operationLog(id)};const review=$('#review-operation');if(review&&o.status==='needs_attention')review.onclick=()=>reviewOperation(o);modalOperation=id}
function reviewOperation(op){openModal('MANUELLE PRÜFUNG',op.name,`<form id="review-form"><div class="hint warn">Zuerst ${['infrastructure','storage_config'].includes(op.action)?'die Infrastrukturkonfiguration':'VM '+op.vmid} und die Aufgaben in Proxmox kontrollieren. Diese Bestätigung führt keine Aktion auf Proxmox aus. Sie dokumentiert die Prüfung und gibt die lokale Aktionssperre frei.</div>${field(['infrastructure','storage_config'].includes(op.action)?'Zielnamen bestätigen':'VM-Name bestätigen','confirm_name','',{placeholder:op.name})}<label for="review-note">Prüfergebnis</label><textarea id="review-note" name="note" required minlength="10" maxlength="500" placeholder="Tatsächlichen Zustand und ggf. Proxmox-Aufgabe festhalten"></textarea><label class="checkbox"><input type="checkbox" name="acknowledge" required> Ich habe den tatsächlichen Zustand in Proxmox geprüft.</label><div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button type="submit" class="primary">Prüfung dokumentieren</button></div></form>`);$('#review-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));setModalBusy(true);try{await api('operations/'+op.id+'/review',{method:'POST',body:JSON.stringify({...d,acknowledge:true})});closeModal(true);await refresh();toast('Prüfung dokumentiert.')}catch(e){setModalBusy(false);formError(e.message)}}}
async function vmAction(vm,action,config={}){const key=newRequestKey();let extra='';if(action==='ha')extra=selectField('HA-Zielzustand','ha_state',option('started','Gestartet halten — startet den Gast')+option('stopped','Gestoppt halten — fährt den Gast herunter')+option('disabled','Deaktiviert — Gast wird gestoppt')+option('ignored','Ignoriert — HA greift nicht ein'));if(action==='snapshot')extra=field('Snapshot-Name','snapshot_name','',{pattern:'[a-zA-Z][a-zA-Z0-9_\\-]{0,39}',placeholder:'before-update'});if(action==='configure')extra=`<div class="formgrid">${field('vCPU','cpu',(config.cores||vm.maxcpu)*(config.sockets||1),{type:'number',min:1,max:128})}${field('RAM · GiB','ram',Math.ceil((config.memory||vm.maxmem/1048576)/1024),{type:'number',min:1,max:1024})}</div>`;if(action==='stop')extra=`<label class="checkbox"><input type="checkbox" name="acknowledge" required> Mir ist bewusst, dass hartes Ausschalten wie Stromkabel-Ziehen wirkt.</label>`;if(action==='template')extra=`<label class="checkbox"><input type="checkbox" name="acknowledge" required> Mir ist bewusst, dass die Umwandlung nicht rückgängig gemacht werden kann.</label>`;if(action==='clone'){const template=!!(vm.template==1),nextId=Math.max(99,...state.resources.filter(r=>r.connection_id===vm.connection_id).map(r=>Number(r.vmid)||0))+1;let nodes=[{node:vm.node,status:'online'}];try{nodes=state.mode==='demo'?[{node:'pve-01',status:'online'},{node:'pve-02',status:'online'},{node:'pve-03',status:'online'}]:await api('connections/'+vm.connection_id+'/nodes')}catch{}extra=`<div class="formgrid">${field('Neue VMID','newid',nextId,{type:'number',min:100,max:999999999})}${field('Name des Klons','new_name',(vm.name||'vm')+'-clone',{pattern:'[a-zA-Z][a-zA-Z0-9\\-]{0,62}'})}${selectField('Ziel-Node','target',nodes.filter(n=>n.status==='online').map(n=>option(n.node,n.node,n.node===vm.node)).join(''))}${field('Ziel-Storage (optional)','storage','',{optional:true,placeholder:'wie Quelle'})}</div><label class="checkbox"><input type="checkbox" name="full" ${template?'':'checked disabled'}> Vollständiger Klon (unabhängige Kopie)${template?'':' · verknüpfte Klone nur von Vorlagen'}</label>`}let choices=[];if(['backup','migrate'].includes(action)){openModal('AKTION VORBEREITEN',operationLabels[action],'<div class="loading">Verfügbare Ziele werden geladen …</div>');try{const targets=action==='migrate'?(state.mode==='demo'?[{node:'pve-01',status:'online'},{node:'pve-02',status:'online'},{node:'pve-03',status:'online'}]:await api('connections/'+vm.connection_id+'/nodes')):[];if(action==='migrate')choices=targets.filter(t=>t.node!==vm.node&&t.status==='online').map(t=>option(t.node,t.node,t.node===config?.target));else{if(state.mode==='demo')choices=[option('pbs-backup','pbs-backup')];else{const module=await api('connections/'+vm.connection_id+'/modules/storage');const resources=module.storage_resources.ok?module.storage_resources.data:[];const storageConfig=module.storage_config.ok?module.storage_config.data:[];choices=storageConfig.filter(s=>s.content?.includes('backup')&&resources.some(r=>r.node===vm.node&&r.storage===s.storage&&r.status!=='unavailable')).map(s=>option(s.storage,s.storage))}}if(!choices.length)throw new Error(action==='migrate'?'Kein anderer Online-Node verfügbar.':'Kein Backup-Storage auf dem Quell-Node gefunden.');if(!modal.open)return;extra=selectField(action==='migrate'?'Ziel-Node':'Backup-Storage',action==='migrate'?'target':'storage',choices.join(''))}catch(e){openModal('AKTION NICHT VERFÜGBAR',operationLabels[action],`<div class="hint error">${esc(e.message)}</div><div class="modal-foot"><button data-cancel>Schließen</button></div>`);return}}const notes={ha:'Konfiguriert die Proxmox-HA-Ressource. Gestartet / Gestoppt / Deaktiviert können den Gast starten oder stoppen. HA benötigt Quorum, geeigneten Storage und funktionierendes Fencing. Dies prüft keine vollständige HA-Eignung. Ignoriert gibt die Kontrolle an die manuelle Verwaltung zurück.',start:'Die VM wird gestartet.',shutdown:'Die VM wird geordnet heruntergefahren. Nicht gespeicherte Gastdaten können betroffen sein.',reboot:'Die VM wird neu gestartet. Dienste werden unterbrochen.',snapshot:'Snapshot ohne RAM-Zustand. Der Storage muss Snapshots unterstützen. Ein Snapshot ersetzt kein Backup.',backup:'Ein Snapshot-Backup wird über vzdump auf das ausgewählte Backup-Storage geschrieben.',migrate:'Migration innerhalb desselben Clusters. Lokale Geräte und Storage-Voraussetzungen können die Migration verhindern. Kein Force-Modus.',configure:'CPU und RAM werden bei gestoppter VM geändert. Die VM bleibt danach gestoppt.',stop:'Der Gast wird sofort ohne Herunterfahren ausgeschaltet. Nicht gespeicherte Daten gehen verloren, Dateisysteme können beschädigt werden.',reset:'Die VM wird sofort hart neu gestartet, ohne das Gastbetriebssystem zu benachrichtigen.',suspend:'Die VM wird angehalten. Arbeitsspeicher bleibt belegt, Dienste antworten nicht mehr bis zum Fortsetzen.',resume:'Eine pausierte VM wird fortgesetzt.',clone:'Erstellt eine Kopie mit neuer VMID. Der Klon wird nicht gestartet. MAC-Adressen werden von Proxmox neu vergeben.',template:'Der Gast wird dauerhaft zur Vorlage. Danach kann er nicht mehr gestartet, sondern nur noch geklont werden.'};openModal('VM '+vm.vmid+' / '+vm.node,operationLabels[action],`<form id="vm-action-form"><div class="hint ${['shutdown','reboot','migrate','stop','reset','suspend','template'].includes(action)?'warn':''}">${notes[action]}</div><p><b>${esc(vm.name)}</b> · ${esc(vm.node)} · VM ${vm.vmid}</p>${extra}${field('Zur Bestätigung den VM-Namen eingeben','confirm_name','',{placeholder:vm.name})}<div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary" type="submit">${state.mode==='demo'?'Simulation starten':operationLabels[action]+' bestätigen'}</button></div></form>`);$('#vm-action-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.confirm_name!==vm.name){formError('Der eingegebene Name stimmt nicht mit der VM überein.');return}const payload={...d,action,connection_id:vm.connection_id,vmid:vm.vmid,node:vm.node,request_key:key};if(action==='configure'){payload.cpu=+d.cpu;payload.ram=+d.ram}if(['stop','template'].includes(action))payload.acknowledge=d.acknowledge==='on';if(action==='clone'){payload.newid=+d.newid;payload.full=vm.template==1?d.full==='on':true;if(!d.storage)delete payload.storage;if(d.target===vm.node)delete payload.target}setModalBusy(true);formError('');try{let op;if(state.mode==='demo'){op={...payload,id:newRequestKey(),name:vm.name,status:'completed',created:Date.now()/1000,events:[{at:Date.now()/1000,message:'Demo: '+operationLabels[action]+'. Keine Aktion auf echter Infrastruktur.'}]};state.operations.unshift(op);if(action==='snapshot'){const k=vm.connection_id+':'+vm.vmid;state.demoSnapshots[k]=[...(state.demoSnapshots[k]||[]),{name:d.snapshot_name,description:'Demo-Snapshot'}]}if(action==='start'||action==='resume')vm.status='running';if(['shutdown','stop'].includes(action))vm.status='stopped';if(action==='template')vm.template=1;if(action==='clone')state.resources.push({...vm,vmid:+d.newid,name:d.new_name,status:'stopped',cpu:0,mem:0,template:0,node:d.target||vm.node});if(action==='migrate')vm.node=d.target;if(action==='configure'){vm.maxcpu=+d.cpu;vm.maxmem=+d.ram*GiB}}else{op=await api('operations',{method:'POST',body:JSON.stringify(payload)});await refresh(false)}closeModal(true);nav('jobs');operationLog(op.id);toast(state.mode==='demo'?'Aktion simuliert.':'Aktion eingeplant.')}catch(e){setModalBusy(false);formError(e.message)}}}

function market(){if(state.marketTab==='custom')return customMarket()+`<div class="hint"><button class="text-button" data-market-tab="central">Zentralen Marketplace öffnen</button></div>`;const c=state.catalog||{packages:[]},packages=(c.packages||[]).filter(p=>(state.category==='Alle'||p.category===state.category)&&(p.name+' '+p.description).toLowerCase().includes(state.query.toLowerCase()));return head('','Marketplace','Zentral gepflegte Pakete. Direkt aus dem Web oder aus deinem lokalen Vorrat.',`<button data-catalog-mode>Downloadmodus</button><button data-catalog-sync ${!c.configured||c.busy?'disabled':''}>${icon('refresh')}${c.busy?'Wird aktualisiert …':'Katalog aktualisieren'}</button>`)+`<div class="dashboard-tabs"><button class="selected">Zentraler Katalog</button><button data-market-tab="custom">Eigene Vorlagen · erweitert</button></div><div class="catalog-status"><span class="dot ${c.error?'amber':''}"></span><b>${c.busy?'Download läuft':c.updated?'Lokaler Katalog verfügbar':'Noch kein lokaler Katalog'}</b><span>${c.revision?esc(c.revision):''} · ${c.mode==='cache'?'Lokaler Vorrat':'Webdownload bei Bedarf'}</span><span class="muted">${c.updated?'Aktualisiert '+when(c.updated):''}</span></div>${c.error?`<div class="hint warn">${esc(c.error)}</div>`:''}${!c.configured?'<div class="hint">Die zentrale Marketplace-Adresse muss vom Herausgeber noch bereitgestellt und bei der Installation hinterlegt werden. Nutzer müssen keine eigenen Vorlagen veröffentlichen.</div>':''}<div class="toolbar"><div class="search">${icon('search')}<input id="market-search" aria-label="Pakete durchsuchen" placeholder="Paket suchen …" value="${esc(state.query)}"></div><span class="small muted">${packages.length} Pakete</span></div><div class="catalog">${packages.map(p=>`<article class="appcard"><div class="appcard-top"><div class="app-logo">${icon('box')}</div><span class="status-tag ${p.cached?'':'neutral'}">${p.cached?'Lokal gespeichert':'Webdownload'}</span></div><div class="category">${esc(p.category)}</div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="appcard-bottom"><span class="tag">${esc(p.version)}</span><button data-catalog-details="${esc(p.id)}">Details</button>${p.deployment?`<button class="primary" data-registry-deploy="${esc(p.id)}">Bereitstellen ${icon('arrow')}</button>`:''}</div></article>`).join('')}</div>${!packages.length?empty('market','Noch keine Pakete verfügbar',c.busy?'Der erste Download läuft. Die Liste wird automatisch aktualisiert.':'Nach erfolgreicher Synchronisierung erscheinen die lokal gespeicherten Pakete hier.'):''}`}
function catalogDetails(id){const p=state.catalog?.packages?.find(p=>p.id===id);if(!p)return;openModal('LOKALER MARKETPLACE',p.name,`<p>${esc(p.description)}</p><div class="hint">${p.deployment?'Cloud-Image-Bereitstellung für Proxmox VE 9+. Basisimage und Cloud-init werden ohne SSH über die Proxmox-API übertragen. Software wird beim ersten Start eingerichtet.':'Für dieses Paket liegt nur eine Datei vor; keine automatische VM-Bereitstellung verfügbar.'}</div>${moduleTable(['Datei','Größe','Download'],p.assets.map(a=>[esc(a.name),fmtBytes(a.size),state.mode==='demo'?'Nur im lokalen Dienst':`<a href="/api/catalog/assets/${esc(a.sha256)}" download>Datei herunterladen</a>`]))}<div class="modal-foot"><button data-cancel>Schließen</button></div>`)}

function newRequestKey(){if(typeof crypto.randomUUID==='function')return crypto.randomUUID();const a=new Uint8Array(16);crypto.getRandomValues(a);a[6]=(a[6]&15)|64;a[8]=(a[8]&63)|128;const h=Array.from(a,b=>b.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20)}
function catalogMode(){const mode=state.catalog?.mode||'web';openModal('MARKETPLACE','Pakete beziehen',`<form id="catalog-mode-form"><div class="mode-options"><label class="mode-option"><input type="radio" name="mode" value="web" ${mode==='web'?'checked':''}><span><b>Aus dem Web herunterladen</b><small>Basisimage erst bei einer Bereitstellung laden. Spart lokalen Speicher und benötigt dann Internet.</small></span></label><label class="mode-option"><input type="radio" name="mode" value="cache" ${mode==='cache'?'checked':''}><span><b>Herunterladen und lokal speichern</b><small>Alle Dateien und Basisimages vorhalten. Der Download kann mehrere GiB benötigen. Gastsoftware kann beim ersten Start weiterhin Internet brauchen.</small></span></label></div><div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary" type="submit">Modus übernehmen</button></div></form>`);$('#catalog-mode-form').onsubmit=async e=>{e.preventDefault();setModalBusy(true);try{if(state.mode==='demo'){state.catalog.mode=new FormData(e.target).get('mode');closeModal(true);render();toast('Demo-Downloadmodus geändert.');return}await api('catalog/config',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal(true);await refresh();toast('Downloadmodus gespeichert. Katalog wird aktualisiert.')}catch(err){setModalBusy(false);formError(err.message)}}}
async function registryDeploy(id){const pkg=state.catalog?.packages?.find(p=>p.id===id);if(!pkg?.deployment)return;const connections=state.connections.filter(c=>c.kind!=='pbs');if(!connections.length){toast('Zuerst Proxmox unter Einstellungen verbinden.');nav('settings');return}const request_key=newRequestKey();let draft={connection_id:state.scope!=='all'&&connections.some(c=>c.id===state.scope)?state.scope:connections[0].id,node:'',name:pkg.id+'-01',username:'orbit',cpu:String(preferences().default_cpu),ram:String(preferences().default_ram),disk:String(preferences().default_disk),ssh:'',vmid:''},nodes=[],targets=null,problem='',generation=0;openModal('REGISTRY / '+pkg.version,pkg.name,'<div class="loading">Zielumgebung wird geprüft …</div>');const epoch=modalEpoch;
function paint(){if(!modal.open||modalEpoch!==epoch)return;const options=(items,value)=>(items||[]).map(v=>option(v,v,v===value)).join('');const valid=targets&&targets.image_storages.length&&targets.import_storages.length&&targets.iso_storages.length&&targets.bridges.length;modal.querySelector('.modal-body').innerHTML=`<form id="registry-form"><p>${esc(pkg.description)}</p>${state.mode==='demo'?'<div class="hint warn">Beispieldaten. Keine Downloads und keine echte VM-Bereitstellung.</div>':''}<div class="formgrid">${selectField('Proxmox-Umgebung','connection_id',connections.map(c=>option(c.id,c.name,c.id===draft.connection_id)).join(''))}${selectField('Ziel-Node','node',nodes.map(n=>option(n.node,n.node,n.node===draft.node)).join(''))}</div>${problem?`<div class="hint error">${esc(problem)}</div>`:''}${targets&&!valid?'<div class="hint warn">Der Node benötigt aktives Image-Storage, Datei-Storage mit Inhaltstyp import und ISO-Storage. Aktiviere den fehlenden Inhaltstyp in der Storage-Verwaltung.</div>':''}${targets?`<div class="formgrid">${selectField('VM-Datenträger','storage',options(targets.image_storages,draft.storage))}${selectField('Zwischenablage für Cloud-Image','import_storage',options(targets.import_storages,draft.import_storage))}${selectField('Cloud-init-ISO speichern auf','iso_storage',options(targets.iso_storages,draft.iso_storage))}${selectField('Netzwerk / DHCP','bridge',options(targets.bridges,draft.bridge))}${field('VMID','vmid',draft.vmid||targets.nextid,{type:'number',min:100,max:999999999})}${field('VM-Name','name',draft.name,{pattern:'[a-zA-Z][a-zA-Z0-9\\-]{0,62}'})}${field('vCPU','cpu',draft.cpu,{type:'number',min:1,max:128})}${field('RAM · GiB','ram',draft.ram,{type:'number',min:1,max:1024})}${field('Systemlaufwerk · GiB','disk',draft.disk,{type:'number',min:8,max:65536})}${field('Cloud-init-Benutzer','username',draft.username,{pattern:'[a-z_][a-z0-9_\\-]{0,30}'})}</div>${field('Öffentlicher SSH-Schlüssel','ssh',draft.ssh,{textarea:true,help:'Für den Login erforderlich. Ausschließlich den öffentlichen Schlüssel einfügen.'})}<div class="hint">${state.catalog?.mode==='cache'?'Image aus dem lokalen Vorrat übertragen.':'Proxmox lädt das Basisimage direkt aus dem Web.'} Neue VM mit DHCP. Softwarepakete werden beim ersten Start im Gast eingerichtet; dafür wird Internet benötigt. Die VM-Erstellung bestätigt noch keine betriebsbereite Anwendung.</div><label class="check"><input type="checkbox" name="start"> Neue VM nach der Erstellung starten</label><label class="check"><input type="checkbox" name="acknowledge" required> Neue VM erstellen; Paket und Zielkonfiguration geprüft</label>`:''}<div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button type="submit" class="primary" ${!valid?'disabled':''}>${state.mode==='demo'?'Demo-Bereitstellung':'VM erstellen'}</button></div></form>`;modal.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=closeModal);const form=$('#registry-form');for(const name of ['connection_id','node'])form.elements[name].onchange=()=>{const values=Object.fromEntries(new FormData(form));draft={...draft,...values};if(name==='connection_id')draft.node='';load()};form.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));const payload={...d,action:'registry_deploy',package_id:pkg.id,package_version:pkg.version,request_key,vmid:+d.vmid,cpu:+d.cpu,ram:+d.ram,disk:+d.disk,start:form.elements.start.checked,acknowledge:form.elements.acknowledge.checked};setModalBusy(true);try{let op;if(state.mode==='demo'){op={...payload,id:newRequestKey(),status:'completed',created:Date.now()/1000,events:[{at:Date.now()/1000,message:'Demo: keine Datei übertragen und keine echte VM erstellt.'}]};state.operations.unshift(op)}else op=await api('operations',{method:'POST',body:JSON.stringify(payload)});closeModal(true);await refresh();nav('jobs');operationLog(op.id)}catch(err){setModalBusy(false);formError(err.message)}}}
async function load(){const current=++generation;problem='';targets=null;try{nodes=(state.mode==='demo'?[{node:'pve-01',status:'online'},{node:'pve-02',status:'online'}]:await api('connections/'+draft.connection_id+'/nodes')).filter(n=>n.status==='online');const query='connection_id='+encodeURIComponent(draft.connection_id)+(draft.node?'&node='+encodeURIComponent(draft.node):'');const result=state.mode==='demo'?{node:draft.node||'pve-01',nextid:200,image_storages:['ceph-pool'],import_storages:['local'],iso_storages:['local'],bridges:['vmbr0']}:await api('catalog/targets?'+query);if(current!==generation||modalEpoch!==epoch)return;targets=result;draft.node=result.node;if(!draft.vmid)draft.vmid=String(result.nextid)}catch(err){if(current!==generation||modalEpoch!==epoch)return;problem=err.message;if(!draft.node&&nodes.length)draft.node=nodes[0].node}paint()}await load()}

function enableImport(key){const[cid,storage]=key.split(':');openModal('STORAGE-KONFIGURATION','Cloud-Image-Import freigeben',`<form id="enable-import-form"><div class="hint warn">Ergänzt den Inhaltstyp import für <b>${esc(storage)}</b> in der clusterweiten Storage-Konfiguration. Bestehende Inhaltstypen bleiben erhalten. Es werden keine VMs gestartet, gestoppt oder gelöscht.</div>${field('Zur Bestätigung Storage-Namen eingeben','confirm_storage','',{placeholder:storage})}<div data-form-error class="hint error"></div><div class="modal-foot"><button data-cancel type="button">Abbrechen</button><button class="primary" type="submit">Import freigeben</button></div></form>`);$('#enable-import-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.confirm_storage!==storage){formError('Storage-Name stimmt nicht überein.');return}setModalBusy(true);try{if(state.mode==='demo')toast('Demo: Storage-Änderung simuliert.');else await api('connections/'+cid+'/storage-content',{method:'POST',body:JSON.stringify({...d,storage})});closeModal(true);loadModule('storage',true)}catch(err){setModalBusy(false);formError(err.message)}}}
const preferenceDefaults={theme:'slate',density:'comfortable',font_size:'normal',refresh_seconds:30,default_cpu:2,default_ram:4,default_disk:32};
function preferences(){return {...preferenceDefaults,...state.preferences}}
function applyPreferences(){const p=preferences(),root=document.documentElement;if(root){root.dataset.theme=p.theme;root.dataset.density=p.density;root.dataset.fontSize=p.font_size}try{localStorage.setItem('orbit-preferences',JSON.stringify(p))}catch{}}
try{state.preferences={...preferenceDefaults,...JSON.parse(localStorage.getItem('orbit-preferences')||'{}')}}catch{state.preferences={...preferenceDefaults}}applyPreferences();
function settings(){const p=preferences(),tab=state.settingsTab||'appearance',tabs=[['appearance','Darstellung'],['connections','Verbindungen'],['defaults','VM-Standards'],['marketplace','Marketplace'],['users','Benutzer & Rollen'],['account','Konto & Sicherheit'],['system','System & Sicherung']];let content='';if(tab==='users')content=typeof usersView==='function'?usersView():'';
if(tab==='appearance')content=`<section class="settings-card"><div class="settings-card-head"><span class="settings-symbol">${icon('grid')}</span><div><h2>Darstellung</h2><p>Farbschema, Lesbarkeit und Abstände für die tägliche Arbeit.</p></div></div><form id="preferences-form"><label>Farbschema</label><div class="theme-options">${[['slate','Orbit Hell','Hell mit dunkler Navigation · Standard'],['slate-dark','Orbit Dunkel','Dunkel mit orangem Akzent'],['graphite','Graphit','Schiefer & Blau'],['cloud','Cloud','Indigo & Lavendel'],['ocean','Ocean','Petrol & Mint'],['dusk','Dusk','Dunkelblau & Flieder']].map(([id,name,desc])=>`<label class="theme-choice"><input type="radio" name="theme" value="${id}" ${p.theme===id?'checked':''}><span class="theme-swatch ${id}"><i></i><i></i><i></i></span><b>${name}</b><small>${desc}</small></label>`).join('')}</div><div class="formgrid">${preferenceSelect('Schriftgröße','font_size',[['normal','Normal · 14 px'],['large','Groß · 16 px']],p.font_size)}${preferenceSelect('Tabellenabstände','density',[['comfortable','Komfortabel'],['compact','Kompakt']],p.density)}${preferenceSelect('Fallback-Aktualisierung','refresh_seconds',[[0,'Aus · manuell'],[15,'Alle 15 Sekunden'],[30,'Alle 30 Sekunden'],[60,'Jede Minute'],[120,'Alle 2 Minuten']],p.refresh_seconds)}</div><div class="settings-save"><span>Schriften lokal eingebunden (Inter, Orbit Sans). Keine externen Schriftanbieter.</span><button class="primary">Darstellung speichern</button></div><div class="hint error" data-settings-error></div></form></section>`;
if(tab==='defaults')content=`<section class="settings-card"><h2>Standardressourcen für neue VMs</h2><p>Werte für den Marketplace-Konfigurator und neue ISO-VMs. Bestehende Gäste bleiben unverändert.</p><form id="defaults-form"><div class="formgrid">${field('vCPUs','default_cpu',p.default_cpu,{type:'number',min:1,max:128})}${field('Arbeitsspeicher · GiB','default_ram',p.default_ram,{type:'number',min:1,max:1024})}${field('Systemlaufwerk · GiB','default_disk',p.default_disk,{type:'number',min:8,max:65536})}</div><div class="hint">Ein Gast startet weiterhin erst, wenn du die Startoption ausdrücklich auswählst.</div><div class="settings-save"><span>Bei jeder Bereitstellung individuell anpassbar.</span><button class="primary">Standards speichern</button></div><div class="hint error" data-settings-error></div></form></section>`;
if(tab==='connections')content=`<section class="settings-card"><div class="panelhead"><div><h2>Proxmox-Verbindungen</h2><p>Direkte APIs, vertrauenswürdige Zertifikate und Ausweichadressen.</p></div><button class="primary" data-action="connection">${icon('plus')} Verbindung hinzufügen</button></div>${state.connections.map(c=>`<div class="settings-connection"><span class="settings-symbol">${icon('server')}</span><div><b>${esc(c.name)}</b><p>${esc(c.active_endpoint||c.url)}</p><small>${c.kind==='pbs'?'Proxmox Backup Server':'Proxmox VE'} · ${(c.endpoints||[]).length+1} API-Endpunkte</small></div><div class="actions"><button data-edit-connection="${esc(c.id)}">Bearbeiten</button><button class="danger ghost" data-remove-connection="${esc(c.id)}">Entfernen</button></div></div>`).join('')||'<div class="empty"><h2>Noch keine Verbindung</h2><p>Ersten Proxmox-Cluster oder Backup Server verbinden.</p></div>'}<div class="hint">Zusätzliche Node-Adressen aktivieren automatischen Lese-Failover. Die Zertifikatsprüfung bleibt aktiv; eigene CAs werden im Container eingebunden.</div></section>`;
if(tab==='marketplace')content=`<section class="settings-card"><h2>Zentraler Marketplace</h2><p>Veröffentlichte Pakete aus der Orbit-Registry – direkt herunterladen oder lokal vorhalten.</p><div class="settings-connection"><span class="settings-symbol">${icon('market')}</span><div><b>${state.catalog?.mode==='cache'?'Lokaler Vorrat':'Webdownload bei Bedarf'}</b><p>${state.catalog?.packages?.length||0} Pakete · ${esc(state.catalog?.revision||'Noch kein Katalog')}</p></div><button data-catalog-mode>Downloadmodus ändern</button><button data-catalog-sync ${state.catalog?.busy?'disabled':''}>Jetzt synchronisieren</button></div><form id="source-form">${field('Katalogadresse · HTTPS','url',state.systemStatus?.saved_catalog_source||state.systemStatus?.catalog_source||'',{type:'url',help:'Eine neue Quelle wird beim nächsten Orbit-Neustart aktiv. Der Downloadmodus lässt sich sofort ändern.'})}<div class="settings-save"><span>Bestehende VMs werden durch Katalogupdates nicht verändert.</span><button class="primary">Quelle speichern</button></div><div class="hint error" data-settings-error></div></form></section>`;
if(tab==='account')content=`<section class="settings-card"><h2>Passwort ändern${state.user?.username?' · '+esc(state.user.username):''}</h2><p>Nach dem Ändern werden andere Sitzungen automatisch abgemeldet.</p><form id="password-form"><div class="formgrid">${field('Aktuelles Passwort','current_password','',{type:'password',autocomplete:'current-password'})}${field('Neues Passwort','new_password','',{type:'password',autocomplete:'new-password',help:'Mindestens 12 Zeichen.'})}${field('Neues Passwort wiederholen','repeat','',{type:'password',autocomplete:'new-password'})}</div><div class="settings-save"><span>Diese Sitzung bleibt geöffnet.</span><button class="primary">Passwort ändern</button></div><div class="hint error" data-settings-error></div></form></section><section class="settings-card"><div class="panelhead"><div><h2>Sitzungen</h2><p>${state.sessions?.length??'…'} aktive Sitzungen. Konsolen anderer Sitzungen werden ebenfalls beendet.</p></div><button data-revoke-sessions>Andere Sitzungen abmelden</button></div>${(state.sessions||[]).map(s=>`<div class="session-row"><span class="dot"></span><b>${s.current?'Diese Sitzung':'Weitere Sitzung'}</b><span>Gültig bis ${when(s.expires)}</span></div>`).join('')}</section>${typeof accountExtras==='function'?accountExtras():''}`;
if(tab==='system'){const s=state.systemStatus||{};content=`<section class="settings-card"><h2>Systemstatus</h2><p>Betriebsinformationen ohne API-Token oder andere Zugangsdaten.</p><dl class="system-facts"><dt>Laufzeit</dt><dd>Go · ${esc(s.version||'0.13.1')}</dd><dt>Öffentliche Adresse</dt><dd>${esc(s.public_origin||'Demo')}</dd><dt>Proxmox-CA</dt><dd>${s.ca==='configured'?'Eigene CA eingebunden':s.ca==='unreadable'?'CA-Datei nicht lesbar':'System-Zertifikatsspeicher'}</dd><dt>Katalogaktualisierung</dt><dd>Beim Start und alle 6 Stunden</dd><dt>Serverzeit</dt><dd>${esc(s.server_time||'Demo')}</dd></dl><button data-reload-system>${icon('refresh')} Status aktualisieren</button></section><section class="settings-card"><h2>Workspace-Sicherung herunterladen</h2><p>Konsistente Datenbanksicherung mit dem Schlüssel für die gespeicherten Zugangsdaten. Enthält keine Proxmox-VM-Backups oder großen Image-Dateien.</p><button class="primary" data-backup-download>${icon('storage')} Sicherung erstellen & herunterladen</button><div class="hint">Die Datei enthält sensible Zugangsdaten. Bewahre sie geschützt auf. Wiederherstellen auf dem Docker-Host: <code>bash scripts/restore.sh backups/DATEI.tar.gz</code></div></section>`}
if(tab==='connections')content+=`<section class="settings-card"><div class="panelhead"><div><h2>Eigene Vorlagen</h2><p>Verknüpfte Proxmox-Blueprints verwalten.</p></div><button data-action="blueprint">Blueprint hinzufügen</button></div>${state.blueprints.map(b=>`<div class="settings-connection"><div><b>${esc(b.name)}</b><p>${esc(b.node)} · Vorlage ${Number(b.template_vmid)}</p></div><button class="danger ghost" data-delete-bp="${esc(b.id)}">Blueprint entfernen</button></div>`).join('')||'<p>Noch keine eigenen Vorlagen verknüpft.</p>'}</section>`;
return head('WORKSPACE','Einstellungen','Darstellung, Verbindungen, Standardwerte, Zugang und Systemverwaltung.')+`<div class="settings-layout"><nav class="settings-nav" aria-label="Einstellungsbereiche">${tabs.map(([id,label])=>`<button data-settings-tab="${id}" class="${tab===id?'selected':''}">${label}${icon('arrow')}</button>`).join('')}</nav><div class="settings-content">${state.settingsError?`<div class="hint error">${esc(state.settingsError)}</div>`:''}${content}</div></div>`}
function preferenceSelect(label,name,choices,value){return `<div class="field"><label for="pref-${name}">${label}</label><select id="pref-${name}" name="${name}">${choices.map(([v,text])=>option(v,text,String(v)===String(value))).join('')}</select></div>`}
async function loadSettingsDetails(){state.settingsError='';if(state.mode==='demo'){state.sessions=[{current:true,expires:Date.now()/1000+3600}];state.systemStatus={version:'0.13.1',runtime:'go',public_origin:'Demo',ca:'configured',catalog_source:'https://quadrix-hd.github.io/orbit-central/catalog.json'};render();return}try{[state.systemStatus,state.sessions]=await Promise.all([api('system/status'),api('account/sessions')])}catch(e){state.settingsError=e.message}if(state.page==='settings'&&['account','marketplace','system'].includes(state.settingsTab)&&!document.activeElement?.closest?.('form'))render()}
function bindSettings(){
$$('[data-settings-tab]').forEach(b=>b.onclick=()=>{state.settingsTab=b.dataset.settingsTab;render();loadSettingsDetails()});
for(const [id,isDefaults]of [['preferences-form',false],['defaults-form',true]]){const form=document.querySelector('#'+id);if(form)form.onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(form)),data={...preferences(),...values};for(const k of ['refresh_seconds','default_cpu','default_ram','default_disk'])data[k]=Number(data[k]);await settingsSubmit(form,async()=>{if(state.mode==='live')state.preferences=await api('settings',{method:'POST',body:JSON.stringify(data)});else state.preferences=data;applyPreferences();render();toast(isDefaults?'VM-Standards gespeichert.':'Darstellung gespeichert.')})}}
const password=document.querySelector('#password-form');if(password)password.onsubmit=async e=>{e.preventDefault();await settingsSubmit(password,async()=>{const d=Object.fromEntries(new FormData(password));if(d.new_password.length<12||d.new_password!==d.repeat)throw new Error('Neue Passwörter müssen übereinstimmen und mindestens 12 Zeichen enthalten.');if(state.mode==='demo')throw new Error('Passwortänderung ist nur im lokalen Go-Dienst verfügbar.');await api('account/password',{method:'POST',body:JSON.stringify(d)});password.reset();toast('Passwort geändert. Andere Sitzungen wurden abgemeldet.');loadSettingsDetails()})};
const source=document.querySelector('#source-form');if(source)source.onsubmit=async e=>{e.preventDefault();await settingsSubmit(source,async()=>{if(state.mode==='demo')throw new Error('Eine eigene Quelle kannst du im lokalen Go-Dienst speichern.');await api('catalog/source',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(source)))});toast('Quelle gespeichert. Mit docker compose restart orbit aktivieren.');loadSettingsDetails()})};
$$('[data-reload-system]').forEach(b=>b.onclick=loadSettingsDetails);$$('[data-revoke-sessions]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{if(state.mode==='demo')throw new Error('Sitzungsverwaltung ist nur im lokalen Dienst verfügbar.');await api('account/sessions/revoke',{method:'POST',body:JSON.stringify({acknowledge:true})});await loadSettingsDetails();toast('Andere Sitzungen abgemeldet.')}catch(e){toast(e.message)}finally{b.disabled=false}});
$$('[data-backup-download]').forEach(b=>b.onclick=async()=>{if(state.mode==='demo'){toast('Echte Sicherungen erstellst du im lokalen Go-Dienst.');return}b.disabled=true;try{const r=await fetch('/api/system/backup',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Orbit-CSRF':state.csrf},body:'{}',signal:AbortSignal.timeout(90000)});if(!r.ok){const d=await r.json();throw new Error(d.error||'Sicherung fehlgeschlagen.')}const blob=await r.blob(),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='orbit-backup-'+new Date().toISOString().slice(0,10)+'.tar.gz';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Sicherung erstellt. Download gestartet.')}catch(e){toast(e.message)}finally{b.disabled=false}});
$$('[data-remove-connection]').forEach(b=>b.onclick=()=>removeConnection(b.dataset.removeConnection));
}
async function settingsSubmit(form,action){const button=form.querySelector('button.primary'),error=form.querySelector('[data-settings-error]');button.disabled=true;error.textContent='';try{await action()}catch(e){error.textContent=e.message}finally{button.disabled=false}}
function removeConnection(id){const c=state.connections.find(c=>c.id===id);if(!c)return;openModal('VERBINDUNG ENTFERNEN',c.name,`<p>Entfernt nur die Verbindung aus Orbit. Gäste, Hosts und deren Daten bleiben erhalten. Offene Aufgaben und zugehörige Blueprints müssen zuerst abgeschlossen bzw. entfernt werden.</p><form id="remove-connection-form">${field('Verbindungsnamen bestätigen','confirm_name','')}<div data-form-error class="hint error"></div><div class="modal-foot"><button type="button" data-cancel>Abbrechen</button><button class="primary danger">Verbindung entfernen</button></div></form>`);$('#remove-connection-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.confirm_name!==c.name){formError('Verbindungsname stimmt nicht überein.');return}setModalBusy(true);try{if(state.mode==='demo')throw new Error('Demo-Verbindungen bleiben als Beispieldaten erhalten.');await api('connections/'+id+'/delete',{method:'POST',body:JSON.stringify(d)});closeModal(true);await refresh();toast('Verbindung entfernt.')}catch(e){setModalBusy(false);formError(e.message)}}}
